window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-113"]=[{"id":"set2-qK7qXSqT","fingerprint":"3da89f63e07096d4","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Ce structură anatomică este afectată în mod specific în gingivite?","options":[{"id":"A","text":"Gingia, ca parte a parodonțiului superficial."},{"id":"B","text":"Osul alveolar."},{"id":"C","text":"Numai papila interdentară."},{"id":"D","text":"Ligamentul parodontal și cementul radicular."},{"id":"E","text":"Toate componentele parodonțiului, inclusiv cel de susținere."}],"correct":["A"],"pages":[330],"source":"set-2"},{"id":"set2-dqfxyR7q","fingerprint":"ff9ef88200af3608","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următorii factori sunt considerați factori de risc sistemici ce influențează evoluția, severitatea și extinderea gingivitei?","options":[{"id":"A","text":"Dezechilibrele hormonale, precum cele din pubertate sau sarcină."},{"id":"B","text":"Medicația."},{"id":"C","text":"Factorii de retenție a biofilmului plăcii bacteriene."},{"id":"D","text":"Fumatul."},{"id":"E","text":"Xerostomia."}],"correct":["A","B","D"],"pages":[330],"source":"set-2"},{"id":"set2-pjLiG5BB","fingerprint":"6fbdeace585917f0","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care este o caracteristică fundamentală a gingivitei induse de placa bacteriană?","options":[{"id":"A","text":"Se extinde în mod constant la cement, ligament parodontal și os alveolar."},{"id":"B","text":"Este o afecțiune reversibilă prin controlul plăcii bacteriene și tratament."},{"id":"C","text":"Este cauzată doar de răspunsul imun al gazdei, independent de biofilm."},{"id":"D","text":"Apare exclusiv pe un parodonțiu redus, afectat anterior."},{"id":"E","text":"Leziunea inflamatorie este localizată la nivelul gingiei."}],"correct":["B","E"],"pages":[330],"source":"set-2"},{"id":"set2-IwrQQaQX","fingerprint":"1993433197cf6f54","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele manifestări fac parte din simptomatologia subiectivă a gingivitei simple?","options":[{"id":"A","text":"Discrete dureri la periaj și la masticația alimentelor dure."},{"id":"B","text":"Ușor prurit gingival."},{"id":"C","text":"Sângerarea provocată de explorarea cu sonda."},{"id":"D","text":"Sângerarea la atingerea și presiunea exercitată de alimente în cursul masticației."},{"id":"E","text":"Senzație de usturime."}],"correct":["A","B","E"],"pages":[330],"source":"set-2"},{"id":"set2-q-4hwqsP","fingerprint":"73c5f2124c00df42","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este considerat principalul semn clinic obiectiv al gingivitei simple?","options":[{"id":"A","text":"Sângerarea gingivală."},{"id":"B","text":"Senzația de usturime."},{"id":"C","text":"Pruritul gingival."},{"id":"D","text":"Durerea la masticația alimentelor acre."},{"id":"E","text":"Senzația de gingie inflamată sesizată de pacient."}],"correct":["A"],"pages":[330],"source":"set-2"},{"id":"set2-8z86L3f3","fingerprint":"d704c8b73c68bc74","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"În ce zone anatomice se localizează inflamația cronică în gingivita simplă?","options":[{"id":"A","text":"La nivelul papilei."},{"id":"B","text":"La nivelul osului alveolar."},{"id":"C","text":"La nivelul gingiei fixe, keratinizate."},{"id":"D","text":"La nivelul ligamentului parodontal."},{"id":"E","text":"La nivelul marginii gingivale libere."}],"correct":["A","C","E"],"pages":[330],"source":"set-2"},{"id":"set2-Ty40Lz6B","fingerprint":"38d09e6e90cf8d79","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele reprezintă semne clinice ale inflamației în gingivita cronică?","options":[{"id":"A","text":"Culoarea roșie deschisă a gingiei, cauzată de hiperemia activă."},{"id":"B","text":"Suprafața gingiei devine netedă și lucioasă, pierzând aspectul de „coajă de portocală”."},{"id":"C","text":"Consistența gingiei este întotdeauna fermă, indiferent de forma clinică."},{"id":"D","text":"Apariția de pungi false prin edem inflamator."},{"id":"E","text":"Desprinderea epiteliului joncțional de pe suprafața dintelui."}],"correct":["A","B","D"],"pages":[331],"source":"set-2"},{"id":"set2-JFcf4fLv","fingerprint":"8637e3eb3fe65b5a","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Ce stadiu al leziunilor tisulare indică trecerea de la gingivită la parodontită?","options":[{"id":"A","text":"Leziunea stabilă"},{"id":"B","text":"Leziunea inițială"},{"id":"C","text":"Leziunea avansată"},{"id":"D","text":"Leziunea precoce"},{"id":"E","text":"Leziunea reversibilă"}],"correct":["C"],"pages":[331],"source":"set-2"},{"id":"set2-rx0OHbve","fingerprint":"6afb04a926a09781","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este aspectul radiologic specific în gingivita cronică propriu-zisă?","options":[{"id":"A","text":"Resorbție osoasă verticală în zona furcațiilor."},{"id":"B","text":"Prezența radiotransparenței difuze la nivelul septurilor interdentare."},{"id":"C","text":"Lărgirea spațiului periodontal la nivelul crestelor alveolare."},{"id":"D","text":"Îngroșarea laminei dura."},{"id":"E","text":"Absența semnelor de interesare a osului alveolar."}],"correct":["E"],"pages":[331],"source":"set-2"},{"id":"set2-ow0SDX1K","fingerprint":"491640eb9d4a0c06","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următorii factori favorizanți pot contribui la transformarea unei gingivite simple în una hiperplazică?","options":[{"id":"A","text":"Obturații cu suprafață rugoasă, retentivă, în vecinătatea gingiei."},{"id":"B","text":"Cavități carioase localizate exclusiv pe suprafața ocluzală."},{"id":"C","text":"Obturații aproximale care nu restabilesc punctul de contact interdentar."},{"id":"D","text":"Contactul traumatic și retentiv al unor aparate ortodontice cu gingia."},{"id":"E","text":"Utilizarea regulată a aței dentare pentru igienizarea spațiilor interdentare."}],"correct":["A","C","D"],"pages":[331],"source":"set-2"},{"id":"set2-uD8SmK5c","fingerprint":"26e729ca138eef14","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce descrie corect aspectul clinic al hiperplaziei papilei interdentare?","options":[{"id":"A","text":"O tumefacție de formă alungită, fuziformă, ce poate ajunge aproape de marginea incizală."},{"id":"B","text":"O modificare de volum strict limitată la baza papilei, fără extindere coronară."},{"id":"C","text":"O retracție a papilei cu expunerea rădăcinii dentare."},{"id":"D","text":"O colorație alb-cenușie a papilei, cu aspect necrotic."},{"id":"E","text":"O tumefacție de formă hemisferică, ce acoperă parțial coroana dintelui."}],"correct":["A","E"],"pages":[331],"source":"set-2"},{"id":"set2--mXpHvSs","fingerprint":"95f0bb16e32c15fe","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Referitor la gingivita la pubertate, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Speciile bacteriene des implicate includ Prevotella intermedia și Capnocytophaga."},{"id":"B","text":"Este mai frecventă la grupa de vârstă 11-14 ani."},{"id":"C","text":"Clinic, se manifestă printr-o inflamație gingivală cu o culoare roșie-violacee."},{"id":"D","text":"Apare exclusiv la fete, din cauza modificărilor hormonale specifice."},{"id":"E","text":"Edemul inflamator asociat este ireversibil, necesitând intervenție chirurgicală."}],"correct":["A","B","C"],"pages":[331],"source":"set-2"},{"id":"set2-X95PSNw9","fingerprint":"36f44e3d85e7d357","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt semnele clinice caracteristice gingivitei de pubertate?","options":[{"id":"A","text":"Ușoară creștere a mobilității dentare fiziologice."},{"id":"B","text":"Senzație de uscăciune și de arsură la nivelul mucoasei gingivale."},{"id":"C","text":"Inflamație gingivală cu o culoare roșie-violacee și tumefacție prin edem reversibil."},{"id":"D","text":"După pubertate, inflamația și tumefacția se reduc, dar uneori este necesară gingivectomia."},{"id":"E","text":"Hiperplazie gingivală, în special vestibulară, cu aspect bulbos al papilei interdentare."}],"correct":["C","D","E"],"pages":[332],"source":"set-2"},{"id":"set2-eGdgEBtA","fingerprint":"5e11067d43aaf3be","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce manifestări pot apărea în gingivita catamenială cu câteva zile înaintea ciclului menstrual?","options":[{"id":"A","text":"Creșterea volumului lichidului șanțului gingival."},{"id":"B","text":"Senzații anormale de gust, precum acru sau sărat."},{"id":"C","text":"Apariția de pungi parodontale adevărate."},{"id":"D","text":"Senzație de tensiune și ușoară tumefacție gingivală."},{"id":"E","text":"Hiperplazie gingivală cu aspect tumoral."}],"correct":["A","D"],"pages":[332],"source":"set-2"},{"id":"set2-xYTiNKD6","fingerprint":"11fbb5933d976850","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care este mecanismul etiopatogenic principal al gingivitei de sarcină?","options":[{"id":"A","text":"O disfuncție ovariană preexistentă care se agravează în sarcină."},{"id":"B","text":"Proliferarea crescută a bacteriilor anaerobe stimulată de hormonii steroizi."},{"id":"C","text":"Sarcina, prin ea însăși, produce direct leziunile gingivale."},{"id":"D","text":"Modificările hormonale din timpul sarcinii influențează reacția țesuturilor locale la placa bacteriană."},{"id":"E","text":"O reducere a fluxului salivar care duce la acumularea de placă."}],"correct":["B","D"],"pages":[332],"source":"set-2"},{"id":"set2-UQ8PZC9b","fingerprint":"1ffa3b9c3fc8d374","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect simptomatologia gingivitei de sarcină?","options":[{"id":"A","text":"Hiperplazia se dezvoltă mai mult pe seama papilelor interdentare și poate avea aspect tumoral."},{"id":"B","text":"Gingia are o consistență fermă și este ferm atașată de dinte."},{"id":"C","text":"Sângerarea se produce la cele mai mici atingeri datorită hipervascularizației și meiopragiei capilare."},{"id":"D","text":"Pot apărea pungi parodontale adevărate și mobilitate patologică de gradul 1 și 2."},{"id":"E","text":"Durerile gingivale sunt constante și intense pe tot parcursul sarcinii."}],"correct":["A","C","D"],"pages":[332],"source":"set-2"},{"id":"set2-j2Ee2f3j","fingerprint":"f8d44869d7c5bb6f","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce denumire alternativă are gingivostomatita de menopauză și în ce contexte poate apărea?","options":[{"id":"A","text":"Se numește “tumora de sarcină” și apare după histerectomii sau ovarectomii."},{"id":"B","text":"Se numește “gingivita de pubertate” și apare după sterilizări prin iradiere."},{"id":"C","text":"Se numește “gingivită catamenială” și apare exclusiv în menopauza fiziologică."},{"id":"D","text":"Se numește “gingivita atrofică senilă” și poate apărea în menopauza fiziologică sau după ovarectomii."},{"id":"E","text":"Este obișnuită perioadei climacterium-ului."}],"correct":["D","E"],"pages":[332],"source":"set-2"},{"id":"set2-0hXZqCXv","fingerprint":"1bc054bc7e703fc2","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt simptomele subiective caracteristice gingivostomatitei de menopauză?","options":[{"id":"A","text":"Dificultatea de a purta proteze mobile din cauza senzațiilor dureroase."},{"id":"B","text":"Senzație de uscăciune și de arsură la nivelul mucoasei orale."},{"id":"C","text":"Ușoară creștere a mobilității dentare fiziologice."},{"id":"D","text":"Senzații anormale de gust, cum ar fi acru sau sărat."},{"id":"E","text":"Sângerare gingivală la periaj și masticație."}],"correct":["A","B","D"],"pages":[332],"source":"set-2"},{"id":"set2--6p6fRD5","fingerprint":"048205bd62aab126","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce microorganisme sunt considerate a fi principalele în șanțul gingival în cazul gingivitelor asociate cu diabetul zaharat insulino-dependent?","options":[{"id":"A","text":"Specii de Actinomyces"},{"id":"B","text":"Specii de Streptococ"},{"id":"C","text":"Veillonela parvula"},{"id":"D","text":"Porphyromonas gingivalis"},{"id":"E","text":"Fusobacterium"}],"correct":["A","B","C","E"],"pages":[333],"source":"set-2"},{"id":"set2-HEtByXg5","fingerprint":"0920d4bea3ad931f","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele reprezintă modificări tisulare la nivel gingival induse de diabet?","options":[{"id":"A","text":"Creșterea lumenului capilarelor și arteriolelor pentru a compensa acidoza tisulară."},{"id":"B","text":"Apariția meiopragiei capilare și a suferințelor vasculare arteriale și venoase."},{"id":"C","text":"Subțierea membranei bazale dintre epiteliu și corion pentru a facilita schimburile nutritive."},{"id":"D","text":"Acumularea de compuși intermediari cu acțiune toxică prin acidoză tisulară."},{"id":"E","text":"Apariția nevritei diabetice la nivelul formațiunilor nervoase locale."}],"correct":["B","D","E"],"pages":[333],"source":"set-2"},{"id":"set2-1GjDPTVJ","fingerprint":"8ba092fad83b224a","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt caracteristicile clinice ale gingiei în cursul diabetului?","options":[{"id":"A","text":"Polipi gingivali sesili sau pediculați."},{"id":"B","text":"Sângerări ușoare la atingere și ulcerații frecvente."},{"id":"C","text":"Prezența frecventă a pungilor false."},{"id":"D","text":"O culoare constant palidă și o consistență fermă, fibroasă."},{"id":"E","text":"Hiperplazie gingivală generalizată de tip polipoidal."}],"correct":["A","B","C","E"],"pages":[333],"source":"set-2"},{"id":"set2-tFihAJee","fingerprint":"44348554b192d677","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Ce rol joacă deficitul de vitamina C în patogeneza gingivitei hiperplazice?","options":[{"id":"A","text":"Neutralizează toxinele bacteriene, reducând inflamația gingivală."},{"id":"B","text":"Modifică în sens agravant răspunsul gingival la placa bacteriană."},{"id":"C","text":"Este cauza directă a infecției gingivale, acționând independent de placa bacteriană."},{"id":"D","text":"Inhibă formarea plăcii bacteriene, dar induce un răspuns inflamator autoimun."},{"id":"E","text":"Produce exclusiv atrofie gingivală, fără semne de hiperplazie sau sângerare."}],"correct":["B"],"pages":[333],"source":"set-2"},{"id":"set2-Ygl-j_1N","fingerprint":"76a7908b82e26130","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"În ce grupuri de populație este mai probabil să apară scorbutul?","options":[{"id":"A","text":"La adulții tineri cu un consum ridicat de carbohidrați."},{"id":"B","text":"La sportivii de performanță cu diete hiperproteice."},{"id":"C","text":"La vârstnicii cu deficiențe de nutriție."},{"id":"D","text":"La copiii în primul an de viață."},{"id":"E","text":"La persoanele cu alcoolism."}],"correct":["C","D"],"pages":[333],"source":"set-2"},{"id":"set2-HCo1Zqn3","fingerprint":"76d711630fba75a8","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este consecința principală a modificărilor tisulare precum îngroșarea membranei bazale și reducerea lumenului capilar la nivel gingival în diabet?","options":[{"id":"A","text":"O regenerare accelerată a țesutului gingival datorită unui flux sanguin crescut."},{"id":"B","text":"O reducere a acidozei tisulare locale prin eliminarea rapidă a metaboliților."},{"id":"C","text":"O nutriție deficitară a epiteliului gingival și a corionului subiacent."},{"id":"D","text":"O creștere a rezistenței locale la placa bacteriană."},{"id":"E","text":"Stimularea formațiunilor nervoase locale, ducând la hipersensibilitate."}],"correct":["C"],"pages":[333],"source":"set-2"},{"id":"set2-BcuJVYru","fingerprint":"69cf97a33a270444","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele manifestări clinice sunt asociate cu deficiența de vitamină C la nivel gingival?","options":[{"id":"A","text":"Hiperplazie gingivală cu ulcerații și sângerări la atingeri minime."},{"id":"B","text":"Mobilitate dentară patologică cauzată de edem."},{"id":"C","text":"Apariția de pungi parodontale adevărate în absența plăcii bacteriene."},{"id":"D","text":"Halena."},{"id":"E","text":"Formarea de pungi false."}],"correct":["A","B","D","E"],"pages":[334],"source":"set-2"},{"id":"set2-SWi5p9Cs","fingerprint":"d052e50f1ab55cd3","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Ce factor agravează tabloul simptomatic în deficiența de vitamină C, conducând la apariția de pungi parodontale adevărate și avulsie dentară?","options":[{"id":"A","text":"Fumatul excesiv."},{"id":"B","text":"Stresul psihosomatic."},{"id":"C","text":"O igienă bucală bună."},{"id":"D","text":"Alcoolismul."},{"id":"E","text":"Prezența plăcii bacteriene."}],"correct":["E"],"pages":[334],"source":"set-2"},{"id":"set2-whch0eTR","fingerprint":"e9bf0c63a7470595","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"În ce tip de leucemie se întâlnește cel mai frecvent gingivita hiperplazică?","options":[{"id":"A","text":"Toate tipurile de leucemie, cu aceeași incidență."},{"id":"B","text":"Niciun tip."},{"id":"C","text":"Leucemia subacută."},{"id":"D","text":"Leucemia cronică."},{"id":"E","text":"Leucemia acută."}],"correct":["E"],"pages":[334],"source":"set-2"},{"id":"set2-xxEfBZn5","fingerprint":"03259eb8467f3b34","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele semne și simptome sunt caracteristice gingivitei hiperplazice din leucemie?","options":[{"id":"A","text":"Gingivoragii precoce, datorate trombocitopeniei."},{"id":"B","text":"Prezența de peteșii și infiltrate leucemice la nivelul mucoasei bucale."},{"id":"C","text":"Gingie de culoare roșie-violacee, cianotică."},{"id":"D","text":"Ulcerații nedureroase, neacoperite de false membrane."},{"id":"E","text":"Hiperplazie gingivală extensivă, care poate acoperi coroana dintelui."}],"correct":["A","B","C","E"],"pages":[334],"source":"set-2"},{"id":"set2-_GpFhbK6","fingerprint":"51bc6ec47155dc8f","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este cauza principală a gingivoragiilor precoce în gingivita asociată leucemiei?","options":[{"id":"A","text":"Trombocitopenia leucemică."},{"id":"B","text":"Prezența infiltratelor leucemice."},{"id":"C","text":"Granulocitopenia."},{"id":"D","text":"Hiperplazia gingivală extensivă."},{"id":"E","text":"Suprainfectarea ulcerațiilor."}],"correct":["A"],"pages":[334],"source":"set-2"},{"id":"set2-vM2_k2YK","fingerprint":"b9b5b6fbae4c4c58","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce microorganisme sunt implicate în etiologia gingivitei acute ulcero-necrotice?","options":[{"id":"A","text":"Spirochete precum Treponema denticola și Treponema vincenti."},{"id":"B","text":"Prevotella intermedia."},{"id":"C","text":"Bacili fuziformi, cum ar fi Fusobacterium nucleatum."},{"id":"D","text":"Porphyromonas gingivalis."},{"id":"E","text":"Infiltrate leucemice."}],"correct":["A","B","C","D"],"pages":[334],"source":"set-2"},{"id":"set2-DNVKrEVL","fingerprint":"d05e102ce72dafc1","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele sunt considerate factori favorizanți pentru gingivostomatita acută ulcero-necrotică?","options":[{"id":"A","text":"Boli generale cronice precum sifilisul sau tumorile maligne."},{"id":"B","text":"Factori psihosomatici precum stresul din timpul examenelor."},{"id":"C","text":"Deficitul de vitamine C, B1 și B2."},{"id":"D","text":"Igiena bucală incorectă sau absentă."},{"id":"E","text":"Trombocitopenia."}],"correct":["A","B","C","D"],"pages":[334],"source":"set-2"},{"id":"set2-G150u-aF","fingerprint":"20119abf99a26349","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Ce denumire primește afecțiunea acută ulcero-necrotică atunci când se extinde de la nivel gingival și către alte zone ale mucoasei cavității bucale?","options":[{"id":"A","text":"Gingivită acută ulcero-necrotică."},{"id":"B","text":"Boală parodontală indusă de deficitul de vitamină C."},{"id":"C","text":"Parodontită marginală cronică."},{"id":"D","text":"Hiperplazie gingivală leucemică."},{"id":"E","text":"Gingivostomatită acută ulcero-necrotică."}],"correct":["E"],"pages":[334],"source":"set-2"},{"id":"set2-imoa1Xy0","fingerprint":"66d45083bad0f26c","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care dintre următoarele reprezintă un semn patognomonic în tabloul clinic al unei gingivite acute ulcero-necrotice?","options":[{"id":"A","text":"Hiperplazie generalizată a gingiei fixe, de culoare roz-pal și consistență fermă."},{"id":"B","text":"Prezența unui depozit pseudomembranos de culoare alb-gălbuie."},{"id":"C","text":"Papilele interdentare prezintă la vârf o ulcerație crateriformă, cu aspect “decapitat”."},{"id":"D","text":"Gingivoragii spontane sau provocate de atingeri minime."},{"id":"E","text":"Adenopatie regională dureroasă la palpare."}],"correct":["C"],"pages":[335],"source":"set-2"},{"id":"set2-9amVBhzl","fingerprint":"1411d8075ca5d181","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce manifestări sistemice pot însoți tabloul clinic al unei gingivite acute ulcero-necrotice?","options":[{"id":"A","text":"Cefalee și insomnie."},{"id":"B","text":"Tulburări de tranzit gastrointestinal."},{"id":"C","text":"Febră între 38,5 – 39º C."},{"id":"D","text":"Hipersalivație fluidă."},{"id":"E","text":"Astenie și adinamie."}],"correct":["A","B","C","E"],"pages":[335],"source":"set-2"},{"id":"set2-vXDA9s90","fingerprint":"6f08e913ab2e0a07","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele clase de medicamente sunt cunoscute pentru a induce hiperplazii gingivale?","options":[{"id":"A","text":"Antagoniștii de calciu."},{"id":"B","text":"Anticonvulsivantele de tip hidantoină."},{"id":"C","text":"Antibioticele din clasa penicilinelor."},{"id":"D","text":"Imunosupresoarele de tip ciclosporină."},{"id":"E","text":"Analgezicele non-steroidiene."}],"correct":["A","B","D"],"pages":[335],"source":"set-2"},{"id":"set2-luWhBrsq","fingerprint":"6d67e76eb0d630a9","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este afirmația corectă privind relația dintre hiperplazia gingivală indusă de hidantoină și igiena orală?","options":[{"id":"A","text":"O igienă orală riguroasă poate determina dispariția completă a hiperplaziei în timpul tratamentului."},{"id":"B","text":"Hiperplazia hidantoinică poate apărea chiar și la pacienții cu o igienă bucală bună."},{"id":"C","text":"Placa bacteriană nu influențează în niciun fel evoluția hiperplaziei hidantoinice."},{"id":"D","text":"Acumularea de placă bacteriană și tartru inhibă dezvoltarea hiperplaziei."},{"id":"E","text":"Apariția hiperplaziei este condiționată exclusiv de prezența plăcii bacteriene."}],"correct":["B"],"pages":[335],"source":"set-2"},{"id":"set2-sg4efdIN","fingerprint":"5144ab716a435166","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce caracteristici clinice sunt descriptive pentru hiperplazia gingivală hidantoinică necomplicată de inflamație?","options":[{"id":"A","text":"Debut ca o mărire de volum difuză a gingiei fixe."},{"id":"B","text":"Afectare mai pronunțată pe fața orală a dinților."},{"id":"C","text":"Consistență fermă și aspect lobulat."},{"id":"D","text":"Apariția unui șanț la limita cu mucoasa alveolară sau la baza hiperplaziei."},{"id":"E","text":"Culoare roșie intensă și sângerare la atingere."}],"correct":["C","D"],"pages":[335],"source":"set-2"},{"id":"set2-HnaUGMy-","fingerprint":"a290eb879a3e0afe","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Prin ce se deosebește de obicei hiperplazia gingivală hidantoinică de hiperplazia gingivală idiopatică?","options":[{"id":"A","text":"Posibilitatea de remisiune spontană."},{"id":"B","text":"Localizarea strict la nivelul papilelor interdentare."},{"id":"C","text":"Gradul de afectare a gingiei fixe."},{"id":"D","text":"Vârsta de debut a afecțiunii."},{"id":"E","text":"Prezența sângerării spontane."}],"correct":["C"],"pages":[335],"source":"set-2"},{"id":"set2-wfFxM-RT","fingerprint":"c200fd13d9246e9b","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele acuze subiective sunt frecvent asociate cu gingivita ulcerativă?","options":[{"id":"A","text":"Reducerea sensibilității la alimente fierbinți."},{"id":"B","text":"Halenă intensă."},{"id":"C","text":"Senzație de gură uscată (xerostomie)."},{"id":"D","text":"Dureri intense la atingerea gingiei."},{"id":"E","text":"Senzație de gust metalic și alterat."}],"correct":["B","D","E"],"pages":[335],"source":"set-2"},{"id":"set2-bJFwN73C","fingerprint":"dff9a8c84bd586c6","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt efectele terapeutice ale antagoniștilor de calciu, menționate în contextul acțiunii lor sistemice?","options":[{"id":"A","text":"Relaxarea mușchilor netezi vasculari, cu efect vasodilatator."},{"id":"B","text":"Deprimarea funcției miocardului la nivelul nodulului sinusal și atrioventricular, având un efect antiaritmic."},{"id":"C","text":"Inhibarea contracției miocardului, având un efect antianginos."},{"id":"D","text":"Stimularea funcției nodulului sinusal și atrioventricular, cu efect proaritmic."},{"id":"E","text":"Contracția mușchilor netezi vasculari, cu efect vasoconstrictor."}],"correct":["A","B","C"],"pages":[336],"source":"set-2"},{"id":"set2-2Gnngd6z","fingerprint":"77e027d404dd90c7","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce caracteristici clinice sunt asociate cu hiperplazia gingivală indusă de antagoniștii de calciu?","options":[{"id":"A","text":"Culoarea poate varia de la roșu congestiv la roșu închis, uneori violaceu în zonele de stază."},{"id":"B","text":"Consistența gingiei este inițial moale, devenind fermă pe măsură ce crește în volum."},{"id":"C","text":"Volumul hiperplaziei este constant, independent de doza și durata administrării medicamentului."},{"id":"D","text":"Gingia hiperplazică este ferm aderentă de coroana dintelui și nu poate fi decolată."},{"id":"E","text":"Are un caracter generalizat, cu predominanță vestibulară și în zonele interdentare."}],"correct":["A","E"],"pages":[336],"source":"set-2"},{"id":"set2-LUbhliQO","fingerprint":"b0e04d1d86d4b4ba","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"La pacienții cu o igienă bucală foarte bună care urmează tratament cu antagoniști de calciu, ce formă particulară poate prezenta hiperplazia gingivală?","options":[{"id":"A","text":"O formă ulcerată, acoperită de placarde fibrinoase alb-gălbui."},{"id":"B","text":"O formă caracterizată prin culoare roz pal și absența sângerării."},{"id":"C","text":"O formă generalizată, moale și depresibilă."},{"id":"D","text":"O formă ce implică exclusiv gingia fixă, ocolind papilele interdentare."},{"id":"E","text":"O formă de tip nodular, cu suprafața netedă și consistență fermă."}],"correct":["E"],"pages":[336],"source":"set-2"},{"id":"set2-lGY5gk4v","fingerprint":"dc05449ef207ed88","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt caracteristicile clinice ale hiperplaziei gingivale la pacienții tratați cu ciclosporine?","options":[{"id":"A","text":"Prezintă o tendință redusă de sângerare."},{"id":"B","text":"Are o incidență de aproximativ 50% la pacienții tratați."},{"id":"C","text":"Sângerarea apare independent de inflamația septică bacteriană."},{"id":"D","text":"Gingia este de culoare roșu congestiv și de consistență moale."},{"id":"E","text":"Gingia este de culoare roz și de consistență fermă."}],"correct":["A","E"],"pages":[336],"source":"set-2"},{"id":"set2-bHVL9w-f","fingerprint":"3d2656e28e2d8a91","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Ce caracteristică fundamentală diferențiază gingivitele neinduse de placa bacteriană de cele induse de placă?","options":[{"id":"A","text":"Răspund rapid și complet la tratamentul cu antibiotice sistemice."},{"id":"B","text":"Sunt mai puțin severe din punct de vedere clinic."},{"id":"C","text":"Se localizează exclusiv la nivelul papilelor interdentare."},{"id":"D","text":"Sunt întotdeauna de natură alergică."},{"id":"E","text":"Nu se remit, de obicei, după îndepărtarea plăcii bacteriene."}],"correct":["E"],"pages":[336],"source":"set-2"},{"id":"set2-ztj3nLur","fingerprint":"f88c68590abf98c2","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt unele dintre cauzele posibile ale gingivitei alergice?","options":[{"id":"A","text":"Unele componente din pastele de dinți și apele de gură."},{"id":"B","text":"Extractul de Sapota Zapotilla, un component al gumei de mestecat."},{"id":"C","text":"Tratamentul cu medicamente imunosupresoare, precum ciclosporinele."},{"id":"D","text":"Acumularea de placă bacteriană la nivelul joncțiunii amelo-cementare."},{"id":"E","text":"Traumatismul ocluzal cronic."}],"correct":["A","B"],"pages":[336],"source":"set-2"},{"id":"set2-g3iQy_Ug","fingerprint":"a071a83c5486aedb","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce aspecte clinice și histologice sunt caracteristice gingivitei cu plasmocite?","options":[{"id":"A","text":"O consistență fermă a gingiei și o tendință redusă la sângerare."},{"id":"B","text":"Un bogat infiltrat plasmocitar în corion."},{"id":"C","text":"Prezența în corion a unui infiltrat inflamator dominat de neutrofile."},{"id":"D","text":"Gingia are o culoare roșie intens, care cuprinde papilele, marginea gingivală liberă și gingia fixă."},{"id":"E","text":"Culoarea roșie intensă dispare, de cele mai multe ori, brusc la nivelul joncțiunii mucogingivale."}],"correct":["B","D","E"],"pages":[336],"source":"set-2"},{"id":"set2-LPePd7Yi","fingerprint":"8e3e58a7d2f3dd8f","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele semne clinice sunt caracteristice unei gingivite alergice provocate, de exemplu, de guma de mestecat?","options":[{"id":"A","text":"Culoarea gingiei este roșie intens, extinzându-se de la papilele interdentare până la joncțiunea mucogingivală."},{"id":"B","text":"Gingia sângerează cu ușurință la atingere și în timpul masticației."},{"id":"C","text":"Volumul gingival este crescut, prezentând un aspect ușor granular."},{"id":"D","text":"Apar frecvent semne de cheilită și glosită."},{"id":"E","text":"Consistența gingiei este fermă și rezistentă la palpare."}],"correct":["A","B","C","D"],"pages":[337],"source":"set-2"},{"id":"set2-NmyHnkbO","fingerprint":"88bcd00e252b8730","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce reprezintă gingivitele descuamative din punct de vedere morfologic?","options":[{"id":"A","text":"Tumefacție gingivală cu aspect granular și culoare roșie intens."},{"id":"B","text":"Manifestări gingivale de tip vezicular sau bulos, cu zone de atrofie a epiteliului."},{"id":"C","text":"Leziuni ulcerative confluente, cu un contur policiclic."},{"id":"D","text":"Creșteri gingivale de consistență fermă, cauzate de o reacție la un corp străin."},{"id":"E","text":"Epitelial, se caracterizează printr-o keratină slab reprezentată sau absentă."}],"correct":["B","E"],"pages":[337],"source":"set-2"},{"id":"set2-zcpj0M3d","fingerprint":"9be7bbad4ab8380b","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"În care dintre următoarele circumstanțe pot apărea gingivite descuamative?","options":[{"id":"A","text":"Pemfigus vulgar."},{"id":"B","text":"În cadrul gingivostomatitei herpetice primare."},{"id":"C","text":"După o histerectomie sau la menopauză."},{"id":"D","text":"Reacții de hipersensibilizare la medicamente."},{"id":"E","text":"Lichen plan vezicular sau bulos."}],"correct":["A","C","D","E"],"pages":[337],"source":"set-2"},{"id":"set2-muU5IzvO","fingerprint":"64eacf040e2022d3","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este dimensiunea caracteristică a leziunilor elementare din gingivitele descuamative?","options":[{"id":"A","text":"Ulcerațiile rezultate după spargerea veziculelor sunt superficiale și de culoare galben-gri."},{"id":"B","text":"Vezicula are în general un diametru de până la 5 mm, iar bula poate atinge câțiva centimetri."},{"id":"C","text":"Leziunea elementară este o ulcerație de câțiva centimetri, fără o fază veziculară prealabilă."},{"id":"D","text":"Atât vezicula, cât și bula au dimensiuni sub 1 mm."},{"id":"E","text":"Vezicula măsoară câțiva centimetri, iar bula poate depăși 10 cm."}],"correct":["B"],"pages":[337],"source":"set-2"},{"id":"set2-pEoSyyvZ","fingerprint":"5ab71f8b54834ed4","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Ce proprietăți definitorii are virusul responsabil de gingivostomatita herpetică?","options":[{"id":"A","text":"Este un virus strict dermatotrop, neafectând țesutul nervos."},{"id":"B","text":"Este un virus cu proprietăți oncogene, cauzând transformări maligne."},{"id":"C","text":"Este un virus cu proprietăți dermatotrope și neurotrope."},{"id":"D","text":"Este un virus strict neurotrop, fără afinitate pentru piele."},{"id":"E","text":"Acționează prin inducerea unei reacții de hipersensibilizare."}],"correct":["C"],"pages":[337],"source":"set-2"},{"id":"set2-vtF-Qooi","fingerprint":"9170d083190ce100","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care este evoluția tipică a veziculelor apărute pe mucoasa bucală în gingivostomatita herpetică?","options":[{"id":"A","text":"Confluează pentru a forma o bulă de mari dimensiuni, care se sparge ulterior."},{"id":"B","text":"Se vindecă fără a se sparge, lăsând în urmă zone de atrofie epitelială."},{"id":"C","text":"Se sparg la câteva ore de la apariție, fiind urmate de ulcerații superficiale galben-gri."},{"id":"D","text":"Ulcerațiile rezultate după spargere sunt înconjurate de un halou roșu, inflamator."},{"id":"E","text":"Persistă intacte timp de câteva zile, apoi se acoperă de cruste."}],"correct":["C","D"],"pages":[337],"source":"set-2"},{"id":"set2-ZrYUUNtW","fingerprint":"1015dc4b5bb3f373","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce manifestări sistemice și loco-regionale însoțesc leziunile bucale din gingivostomatita herpetică?","options":[{"id":"A","text":"Halenă și dificultăți de masticație."},{"id":"B","text":"Evoluție asimptomatică din punct de vedere sistemic."},{"id":"C","text":"Adenopatie loco-regională."},{"id":"D","text":"Apariția semnelor de cheilită și glosită."},{"id":"E","text":"Stare generală alterată, cu febră, curbatură și cefalee."}],"correct":["A","C","E"],"pages":[337],"source":"set-2"},{"id":"set2-x4VlEPfW","fingerprint":"9a58cd51b95641e6","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care este evoluția și prognosticul gingivostomatitei herpetice?","options":[{"id":"A","text":"Se vindecă rapid în 48-72 de ore, odată cu apariția imunității."},{"id":"B","text":"Este o afecțiune cronică, cu leziuni persistente care nu se vindecă complet."},{"id":"C","text":"Evoluează în pusee de intensitate descrescătoare și se vindecă total în aproximativ două săptămâni."},{"id":"D","text":"Evoluează într-un singur puseu sever, urmat de eliminarea completă a virusului din organism."},{"id":"E","text":"După prima infecție, se instalează de obicei o imunitate umorală și posibil celulară."}],"correct":["C","E"],"pages":[337],"source":"set-2"},{"id":"set2-NzVJv8vB","fingerprint":"20204a687ef08d0b","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Unde poate supraviețui virusul herpetic după infecția primară, permițând reactivări ulterioare?","options":[{"id":"A","text":"La nivelul joncțiunii mucogingivale."},{"id":"B","text":"În celulele epiteliale ale gingiei."},{"id":"C","text":"În circulația sanguină, sub formă latentă."},{"id":"D","text":"La nivelul ganglionului lui Gasser."},{"id":"E","text":"Reactivarea poate fi declanșată de expunerea la soare."}],"correct":["D"],"pages":[337],"source":"set-2"},{"id":"set2-JJCK5GZk","fingerprint":"100b7cefad1fbff5","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt condițiile favorizante menționate pentru recidiva infecției cu virusul herpetic, care poate descinde de la nivelul ganglionului Gasser?","options":[{"id":"A","text":"Imunitatea activată la vârstnici"},{"id":"B","text":"Expunerea la soare și ciclul menstrual"},{"id":"C","text":"Fumatul și schimbarea periei de dinți"},{"id":"D","text":"Afecțiunile generale gastrointestinale și gripa"},{"id":"E","text":"Traumatismele și extracțiile dentare"}],"correct":["B","D","E"],"pages":[338],"source":"set-2"},{"id":"set2-LttnK2_j","fingerprint":"1da470290e99c6cf","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care dintre următoarele afirmații descrie corect caracteristicile gingivostomatitei aftoase recidivante?","options":[{"id":"A","text":"Recidivele apar la intervale regulate de timp, de obicei la câteva săptămâni."},{"id":"B","text":"Este o afecțiune cu etiologie cunoscută, fiind cauzată de Candida albicans."},{"id":"C","text":"Se caracterizează prin leziuni nedureroase și absența adenopatiei loco-regionale."},{"id":"D","text":"Leziunea elementară este afta, care debutează ca o veziculă cu durată scurtă de viață."},{"id":"E","text":"Apare mai frecvent la copii și este rară la adulți."}],"correct":["D"],"pages":[338],"source":"set-2"},{"id":"set2-mqf83axl","fingerprint":"19d1a5ccddb3d96a","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Ce caracteristici dimensionale și de vindecare sunt asociate cu diferitele tipuri de afte din gingivostomatita aftoasă recidivantă?","options":[{"id":"A","text":"Aftele mari au un contur regulat, rotund și se vindecă fără cicatrice."},{"id":"B","text":"Atât aftele mici, cât și cele mari, se vindecă în același interval de timp, de 7-10 zile."},{"id":"C","text":"Aftele mari au dimensiuni de 0,2-1 cm și persistă timp de câteva săptămâni."},{"id":"D","text":"Aftele mici au dimensiuni de 1-3 cm și se vindecă în 7-10 zile cu cicatrice."},{"id":"E","text":"Aftele mici au un diametru de 0,2-1 cm și se vindecă fără cicatrice în 7-10 zile."}],"correct":["E"],"pages":[338],"source":"set-2"},{"id":"set2-Vpe6EDqi","fingerprint":"9f4b961406658f4e","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele elemente sunt utilizate pentru stabilirea diagnosticului pozitiv al gingivostomatitei aftoase recidivante?","options":[{"id":"A","text":"Apariția concomitentă a leziunilor herpetice în zonele cutaneo-mucoase."},{"id":"B","text":"Testul terapeutic constând în albirea ulcerației la contactul cu soluție de nitrat de argint 30%."},{"id":"C","text":"Apariția mai frecventă a bolii la copii decât la adulți."},{"id":"D","text":"Aspectul clinic al ulcerației și prezența durerilor intense."},{"id":"E","text":"Identificarea microorganismului Candida albicans în leziune."}],"correct":["B","D"],"pages":[338],"source":"set-2"},{"id":"set2-uRVxW0DC","fingerprint":"007201b43b59d495","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Cum se realizează diagnosticul diferențial între gingivostomatita aftoasă recidivantă și gingivostomatita herpetică?","options":[{"id":"A","text":"Ambele afecțiuni au aceeași etiologie, dar manifestări clinice diferite."},{"id":"B","text":"Gingivostomatita aftoasă recidivantă se însoțește frecvent de leziuni în zonele cutaneo-mucoase."},{"id":"C","text":"Gingivostomatita herpetică este mai dureroasă și apare mai des la adulți."},{"id":"D","text":"Doar gingivostomatita aftoasă recidivantă este însoțită de adenopatie loco-regională."},{"id":"E","text":"Gingivostomatita herpetică apare mai frecvent la copii și este mai puțin dureroasă."}],"correct":["E"],"pages":[338],"source":"set-2"},{"id":"set2-Ihr-JjNJ","fingerprint":"c69a1d9a1a36fddb","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este agentul etiologic al gingivitei și gingivostomatitei de cauză micotică și care este particularitatea sa?","options":[{"id":"A","text":"Un microorganism necunoscut, care declanșează mecanisme imunopatologice."},{"id":"B","text":"O bacterie care devine agresivă în condiții de stres."},{"id":"C","text":"Virusul herpetic, care supraviețuiește în ganglionii nervoși."},{"id":"D","text":"Un microorganism care se transmite exclusiv prin picături de salivă."},{"id":"E","text":"Candida albicans, care în mod obișnuit poate fi nepatogenă în cavitatea bucală."}],"correct":["E"],"pages":[338],"source":"set-2"},{"id":"set2--6HuuBnX","fingerprint":"3d3ee54bed7a5e7f","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce simptome sistemice și locale, în afara ulcerației, sunt asociate cu gingivostomatita aftoasă recidivantă?","options":[{"id":"A","text":"Hipersalivație și trismus"},{"id":"B","text":"Adenopatie loco-regională"},{"id":"C","text":"Vindecarea constantă cu cicatrice, indiferent de dimensiunea leziunii"},{"id":"D","text":"Alterarea stării generale cu febră ușoară și inapetență"},{"id":"E","text":"Apariția de leziuni genitale, definind aftoza bipolară"}],"correct":["A","B","D","E"],"pages":[338],"source":"set-2"},{"id":"set2-6O5UMjmj","fingerprint":"20472b46eb443f3f","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este agentul etiologic implicat în apariția gingivitei și gingivostomatitei de cauză micotică?","options":[{"id":"A","text":"Staphylococcus aureus"},{"id":"B","text":"Amoxicilina"},{"id":"C","text":"Tetraciclina"},{"id":"D","text":"Candida albicans"},{"id":"E","text":"Streptococcus mutans"}],"correct":["D"],"pages":[339],"source":"set-2"},{"id":"set2-BNtLabte","fingerprint":"50c2ea45a541dd95","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele condiții sunt considerate factori favorizanți pentru transformarea Candidei albicans într-un microorganism agresiv?","options":[{"id":"A","text":"Tratamentul cu citostatice și doze mari de radiații."},{"id":"B","text":"Consumul excesiv de amoxicilină și tetraciclină."},{"id":"C","text":"Diabetul și hipotiroidismul."},{"id":"D","text":"Administrarea tetraciclinei în doze mici de 0,250 g/zi."},{"id":"E","text":"Sarcina și utilizarea contraceptivelor."}],"correct":["A","B","C","E"],"pages":[339],"source":"set-2"},{"id":"set2-B9dqWN-W","fingerprint":"28a3800cddbcb558","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce caracteristici obiective prezintă leziunile candidozice la copii?","options":[{"id":"A","text":"Depozite de culoare alb-crem, cu aspect de lapte prins, coagulat."},{"id":"B","text":"Depozitele miceliene sunt aderente și se desprind lăsând puncte sângerânde."},{"id":"C","text":"Leziunile se desprind cu ușurință la simpla atingere, fără sângerare."},{"id":"D","text":"Atrofia papilelor filiforme ale limbii."},{"id":"E","text":"Leziunile sunt dispuse pe un fond eritematos generalizat al mucoasei bucale."}],"correct":["A","B","E"],"pages":[339],"source":"set-2"},{"id":"set2-AGcUa1Zr","fingerprint":"9abc07a6b0184187","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele manifestări clinice obiective ale candidozei se întâlnesc la adulți?","options":[{"id":"A","text":"Depozite miceliene care imită laptele prins, dispuse întotdeauna izolat."},{"id":"B","text":"Hiperkeratoza epiteliului cu apariția de plăci albe, aderente."},{"id":"C","text":"Atrofia papilelor filiforme ale limbii, care capătă un aspect neted și lucios."},{"id":"D","text":"Fisuri și ulcerații ale comisurii buzelor cu exudat seros și cruste."},{"id":"E","text":"Aspect pseudomembranos, cu plăci albe de tip lapte închegat pe fond de eritem și ulcerații."}],"correct":["B","C","D","E"],"pages":[339],"source":"set-2"},{"id":"set2-gdQuSpz8","fingerprint":"33922e92ffd327ae","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce efect are administrarea tetraciclinei în doze mici (0,250 g sau 0,500 g/zi) în contextul sănătății gingivale?","options":[{"id":"A","text":"Are efecte benefice în tratamentul unor gingivite și parodontite marginale."},{"id":"B","text":"Favorizează frecvent dezvoltarea unei candidoze."},{"id":"C","text":"Este contraindicată absolut în orice doză din cauza riscului micotic."},{"id":"D","text":"Se concentrează în lichidul șanțului gingival de două-trei ori mai mult ca în sânge."},{"id":"E","text":"Scade concentrația de microorganisme benefice din sânge."}],"correct":["A","D"],"pages":[339],"source":"set-2"},{"id":"set2-dcT9we_r","fingerprint":"f8db6b56ff73df05","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt simptomele subiective raportate de pacienții cu gingivostomatită de cauză micotică?","options":[{"id":"A","text":"Senzații dureroase la atingere și masticație."},{"id":"B","text":"Apariția de fisuri dureroase."},{"id":"C","text":"Sângerări gingivale spontane, neprovocate."},{"id":"D","text":"Dificultatea de a purta protezele mobile."},{"id":"E","text":"Xerostomie severă."}],"correct":["A","B","D"],"pages":[339],"source":"set-2"},{"id":"set2-E-TOlTkA","fingerprint":"4af47fd748f17390","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"În contextul unei micoze acute prelungite și rebele la tratament, ce afecțiune sistemică trebuie luată în considerare?","options":[{"id":"A","text":"Diabetul zaharat."},{"id":"B","text":"Hipotiroidismul."},{"id":"C","text":"Sindromul imunodeficienței dobândite (SIDA)."},{"id":"D","text":"Boala Addison."},{"id":"E","text":"Sarcina."}],"correct":["C"],"pages":[339],"source":"set-2"},{"id":"set2-xjCq_BjN","fingerprint":"f7c3cbc05f656cf2","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt caracteristicile gingivitei induse de placa bacteriană?","options":[{"id":"A","text":"Se extinde în mod invariabil la țesuturile de susținere a dintelui, precum osul alveolar și ligamentul parodontal."},{"id":"B","text":"Rămâne localizată la nivelul structurilor parodonțiului superficial."},{"id":"C","text":"Este o afecțiune ireversibilă care necesită intervenții chirurgicale complexe."},{"id":"D","text":"Apare exclusiv pe un parodonțiu sănătos, neputând debuta pe un parodonțiu redus."},{"id":"E","text":"Reprezintă o leziune inflamatorie apărută în urma interacțiunii dintre biofilmul plăcii bacteriene și răspunsul imun al gazdei."}],"correct":["B","E"],"pages":[330],"source":"set-2"},{"id":"set2-9QyTd-n1","fingerprint":"8ce1f56a918ae880","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următorii factori sunt clasificați ca factori de risc locali (predispozanți) pentru evoluția, severitatea și extinderea gingivitei?","options":[{"id":"A","text":"Fumatul."},{"id":"B","text":"Xerostomia."},{"id":"C","text":"Dezechilibrele hormonale."},{"id":"D","text":"Medicația cronică."},{"id":"E","text":"Factorii de retenție a biofilmului plăcii bacteriene."}],"correct":["B","E"],"pages":[330],"source":"set-2"},{"id":"set2-E9EL2irf","fingerprint":"f6a07434bbe319e4","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele structuri NU sunt afectate de procesul inflamator în gingivita indusă de placa bacteriană?","options":[{"id":"A","text":"Cementul."},{"id":"B","text":"Ligamentul parodontal."},{"id":"C","text":"Osul alveolar."},{"id":"D","text":"Parodonțiul superficial."},{"id":"E","text":"Gingia."}],"correct":["A","B","C"],"pages":[330],"source":"set-2"},{"id":"set2-aTx0Ses4","fingerprint":"bda2d27a6bf600de","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce factori de risc sistemici pot influența evoluția, severitatea și extinderea gingivitei?","options":[{"id":"A","text":"Dezechilibrele hormonale precum sarcina și utilizarea de contraceptive."},{"id":"B","text":"Factorii metabolici și nutriționali."},{"id":"C","text":"Factorii de retenție a biofilmului."},{"id":"D","text":"Xerostomia severă."},{"id":"E","text":"Patologiile sistemice asociate."}],"correct":["A","B","E"],"pages":[330],"source":"set-2"},{"id":"set2-xmL70Ppa","fingerprint":"0f8a4db722fd5a34","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care dintre următoarele afirmații descrie corect o caracteristică clinică obiectivă a gingivitei simple induse de placa bacteriană?","options":[{"id":"A","text":"Epiteliul joncțional se desprinde de pe suprafața dintelui odată cu formarea pungilor gingivale."},{"id":"B","text":"Culoarea roșie deschisă a țesutului gingival este determinată de instalarea hiperemiei active la nivelul vaselor din corion."},{"id":"C","text":"Examenul radiologic evidențiază o pierdere incipientă a osului alveolar la nivelul crestelor septurilor interdentare."},{"id":"D","text":"Suprafața gingiei dobândește un aspect accentuat de „gravură punctată”, reflectând prezența inflamației cronice."},{"id":"E","text":"Sângerarea gingivală se instalează tardiv, fiind precedată în mod constant de modificările de culoare ale țesuturilor parodontale."}],"correct":["B"],"pages":[331],"source":"set-2"},{"id":"set2-5vnP8JJK","fingerprint":"5b9a93c667a14efe","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele manifestări clinice se încadrează în simptomatologia subiectivă a pacientului cu gingivită simplă?","options":[{"id":"A","text":"Sângerări gingivale declanșate la periaj și masticație, care sunt sesizate în mod direct de către pacient."},{"id":"B","text":"Dureri intense și continue la nivelul arcadelor dentare, cu iradiere regională de-a lungul ramurilor nervului trigemen."},{"id":"C","text":"Tumefacția parcelară și mărirea evidentă de volum a papilelor interdentare de formă hemisferică."},{"id":"D","text":"Senzația de usturime resimțită local la nivelul țesuturilor gingivale."},{"id":"E","text":"Prezența unui ușor prurit la nivel gingival."}],"correct":["A","D","E"],"pages":[330],"source":"set-2"},{"id":"set2-AMnCVjxs","fingerprint":"85f6db9649d9deb4","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"În condițiile persistenței îndelungate a plăcii bacteriene (2-3 luni), gingivita simplă poate evolua spre o formă hiperplazică. Care dintre următorii factori locali sunt capabili să favorizeze această evoluție?","options":[{"id":"A","text":"Interesarea vizibilă a osului alveolar cu instalarea secundară a mobilității patologice a dinților stâlpi."},{"id":"B","text":"Impactul alimentar direct asupra papilei dentare survenit consecutiv ne-restabilirii punctului de contact interdentar."},{"id":"C","text":"Contactul traumatic generat de croșetele dentare sau marginile bazei protezelor acrilice asupra țesutului gingival."},{"id":"D","text":"Prezența obturațiilor cu o suprafață rugoasă și retentivă situate în imediata vecinătate a marginii gingivale."},{"id":"E","text":"Dezvoltarea cavităților carioase situate strict pe suprafețele ocluzale ale dinților, fără extindere către perimetrul cervical."}],"correct":["B","C","D"],"pages":[331],"source":"set-2"},{"id":"set2-KwHsz3Aw","fingerprint":"d1506fb986678de6","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Referitor la pungile false (aparente) formate pe parcursul evoluției gingivitei simple, care dintre următoarele caracteristici sunt considerate clinic corecte?","options":[{"id":"A","text":"Mecanismul lor de formare include obligatoriu migrarea apicală și desprinderea epiteliului joncțional de pe suprafața dintelui."},{"id":"B","text":"Pot atinge dimensiuni variabile ce permit acoperirea suprafețelor coronare laterale, extinzându-se până în apropierea marginii incizale."},{"id":"C","text":"Sunt decelate cu o frecvență ridicată în gingivitele hiperplazice și în formele de tranziție spre parodontita cu fenomene hiperplazice."},{"id":"D","text":"Reprezintă consecința unui edem inflamator care prezintă un caracter reversibil în urma aplicării tratamentului antimicrobian."},{"id":"E","text":"Sunt semne patognomonice ale lizei osoase orizontale precoce și anunță debutul distrucției sistemului de atașament parodontal."}],"correct":["B","C","D"],"pages":[331],"source":"set-2"},{"id":"set2-E50z52Pj","fingerprint":"27f10fd49a1a1ec9","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Gingivita simplă prezintă o serie de trăsături fiziopatologice și morfologice specifice. Care dintre afirmațiile următoare referitoare la această afecțiune sunt exacte?","options":[{"id":"A","text":"Dinamica de dezvoltare a hiperplaziei gingivale presupune o mărire de volum cu caracter generalizat și uniform pe ambele arcade dentare."},{"id":"B","text":"Reprezintă o inflamație cronică de cauză pur microbiană localizată la nivelul papilei dentare, marginii gingivale libere și gingiei fixe keratinizate."},{"id":"C","text":"Sângerarea obiectivă poate fi declanșată și de mișcările buzelor, obrajilor sau limbii ce realizează o succiune a papilelor gingivale."},{"id":"D","text":"Evoluția leziunilor instalate la nivel tisular traversează succesiv un stadiu precoce, inițial, stabil și ulterior avansat, cel din urmă sugerând o trecere spre parodontită."},{"id":"E","text":"Consistența gingiei în prezența proceselor inflamatorii de tip exsudativ devine fermă, evidențiind o organizare exclusiv fibrilară a corionului."}],"correct":["B","C","D"],"pages":[330],"source":"set-2"},{"id":"set2-6o6jwblO","fingerprint":"83851fc5908671fb","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care dintre următoarele specii bacteriene sunt cel mai frecvent implicate în patogenia gingivitei de pubertate?","options":[{"id":"A","text":"Veillonella parvula și Actinomyces naeslundii"},{"id":"B","text":"Prevotella intermedia și Capnocytophaga"},{"id":"C","text":"Porphyromonas gingivalis și Treponema denticola"},{"id":"D","text":"Aggregatibacter actinomycetemcomitans și Fusobacterium nucleatum"},{"id":"E","text":"Streptococcus mutans și Lactobacillus acidophilus"}],"correct":["B"],"pages":[331],"source":"set-2"},{"id":"set2-YwtpDl0c","fingerprint":"fa0279ca3e4ac4d0","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt trăsăturile clinice și evolutive caracteristice gingivitei de pubertate?","options":[{"id":"A","text":"Rezolvarea definitivă a hiperplaziei apare exclusiv prin remisiune spontană post-pubertate"},{"id":"B","text":"Tumefacție prin edem cu caracter reversibil"},{"id":"C","text":"Hiperplazie gingivală localizată în special pe versantul oral"},{"id":"D","text":"Inflamația gingivală are o culoare roșie-violacee"},{"id":"E","text":"Papila interdentară capătă un aspect bulbos"}],"correct":["B","D","E"],"pages":[331],"source":"set-2"},{"id":"set2-VzDO7Hua","fingerprint":"190ef1c4b10c6182","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt manifestările clinice ce pot apărea în cadrul gingivitei din cursul ciclului menstrual (catamenială)?","options":[{"id":"A","text":"Prezintă sângerare gingivală"},{"id":"B","text":"Volumul lichidului șanțului gingival scade semnificativ"},{"id":"C","text":"Se manifestă printr-o senzație de tensiune și o ușoară tumefacție gingivală"},{"id":"D","text":"Manifestările clinice se instalează de obicei cu câteva zile după încheierea ciclului menstrual"},{"id":"E","text":"Apare o ușoară creștere a mobilității dentare fiziologice"}],"correct":["A","C","E"],"pages":[332],"source":"set-2"},{"id":"set2-4QZY0MdZ","fingerprint":"fffc92d88ccaf937","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Ce modificare suferă lichidul șanțului gingival în contextul manifestărilor gingivitei catameniale?","options":[{"id":"A","text":"Crește în volum pe seama unui exudat inflamator"},{"id":"B","text":"Își menține un volum constant cantitativ, modificându-și doar vâscozitatea"},{"id":"C","text":"Scade în volum pe fondul vasoconstricției locale premenstruale"},{"id":"D","text":"Crește în volum exclusiv pe seama unui transudat neinflamator"},{"id":"E","text":"Este înlocuit de un exsudat purulent în absența preexistentei unei alte patologii gingivale"}],"correct":["A"],"pages":[332],"source":"set-2"},{"id":"set2-CXd5m_aa","fingerprint":"a10a82f9cd1b7c34","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele afirmații descriu trăsăturile generale și factorii asociați gingivitei de pubertate?","options":[{"id":"A","text":"Simptomatologia se limitează la sângerare provocată exclusiv de periajul dentar"},{"id":"B","text":"Înregistrează o frecvență maximă în intervalul de vârstă cuprins între 11 și 14 ani"},{"id":"C","text":"Rezolvarea definitivă a hiperplaziei necesită uneori o intervenție chirurgicală de gingivectomie"},{"id":"D","text":"Este o afecțiune ce se manifestă exclusiv la pacienții de sex feminin"},{"id":"E","text":"Apare în special în zonele bogate în placă dentară bacteriană și tartru"}],"correct":["B","C","E"],"pages":[331],"source":"set-2"},{"id":"set2-kZ7y2tbL","fingerprint":"8c5f1c05c8df6ed5","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele afirmații referitoare la etiopatogenia gingivitei de sarcină sunt corecte?","options":[{"id":"A","text":"În lichidul șanțului gingival se remarcă o creștere a bacteriei Porphyromonas gingivalis."},{"id":"B","text":"Sarcina constituie cauza directă și principală a apariției inflamației gingivale."},{"id":"C","text":"Hormonii steroizi acționează ca factori de proliferare exclusiv asupra florei bacteriene aerobe."},{"id":"D","text":"Placa bacteriană reprezintă adevărata cauză a gingivitei din cursul sarcinii."},{"id":"E","text":"Afecțiunea are un debut strict cronic, menținându-se constant pe parcursul întregii perioade de gestație."}],"correct":["A","D"],"pages":[332],"source":"set-2"},{"id":"set2-G-UA2Nmn","fingerprint":"061cda81aee236d3","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt caracteristicile clinice și simptomatologice întâlnite în gingivita de sarcină?","options":[{"id":"A","text":"Sângerarea se produce la atingeri minime din cauza meiopragiei capilare și a zonelor ulcerate."},{"id":"B","text":"Culoarea țesutului gingival variază de la roșu viu, strălucitor, până la roșu-violaceu."},{"id":"C","text":"Durerile gingivale au un caracter spontan și permanent, manifestându-se în absența oricărei infecții supraadăugate."},{"id":"D","text":"Gingia are o consistență fermă și este strâns aderentă de suprafața dentară."},{"id":"E","text":"Hiperplazia se dezvoltă în special pe seama papilelor interdentare."}],"correct":["A","B","E"],"pages":[332],"source":"set-2"},{"id":"set2--80rQXOW","fingerprint":"7c4a637a4601e0f1","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este afirmația corectă privind manifestările și evoluția gingivitei de sarcină?","options":[{"id":"A","text":"Mobilitatea patologică a dinților atinge frecvent gradul 3 încă din primele stadii ale bolii."},{"id":"B","text":"Formarea pungilor parodontale adevărate este imposibilă în contextul acestei patologii."},{"id":"C","text":"Hiperplazia de sarcină este strict limitată la nivelul papilelor interdentare, neafectând niciodată alte porțiuni ale gingiei."},{"id":"D","text":"În cazurile grave de suprainfectare, evoluția afecțiunii poate duce până la avulsia dinților."},{"id":"E","text":"Sângerarea gingivală apare exclusiv din cauza depozitelor purulente de pe suprafața mucoasei."}],"correct":["D"],"pages":[332],"source":"set-2"},{"id":"set2-z2NZHAzE","fingerprint":"5f1ff5db3e1a5170","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele aspecte generale definesc gingivita și gingivostomatita de menopauză?","options":[{"id":"A","text":"Constituie o manifestare obișnuită a perioadei climacterium-ului."},{"id":"B","text":"Se mai numește gingivită hiperplazică de sarcină."},{"id":"C","text":"Este o patologie caracteristică exclusiv vârstei copilăriei."},{"id":"D","text":"Afecțiunea este denumită și gingivită atrofică senilă."},{"id":"E","text":"Afectează predominant mucoasa limbii, lăsând gingia intactă."}],"correct":["A","D"],"pages":[332],"source":"set-2"},{"id":"set2-w6Fld1xI","fingerprint":"13bc0dc9e8c07da1","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele simptome subiective sunt caracteristice gingivitei și gingivostomatitei de menopauză?","options":[{"id":"A","text":"Pacienții acuză frecvent senzații anormale de gust, descrise ca dulce sau amar."},{"id":"B","text":"Percepția unor senzații anormale de gust, manifestate sub formă de acru și sărat."},{"id":"C","text":"Purtarea protezelor mobile devine dificilă din cauza senzațiilor dureroase, hiperestezice ale mucoasei bucale."},{"id":"D","text":"Senzațiile dureroase la contactul termic apar exclusiv la consumul de băuturi și alimente reci."},{"id":"E","text":"Apare o senzație de uscăciune și de arsură la nivelul mucoasei gingivale și orale."}],"correct":["B","C","E"],"pages":[332],"source":"set-2"},{"id":"set2-PvFxAYz6","fingerprint":"61ad2dbf22b2305b","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce manifestări obiective se observă la nivelul mucoasei gingivale și orale în gingivita și gingivostomatita de menopauză?","options":[{"id":"A","text":"Culoarea devine uneori mai roșie, moment în care gingia sângerează ușor."},{"id":"B","text":"Mucoasa capătă un aspect uscat, neted și o culoare palidă."},{"id":"C","text":"În anumite cazuri, apar fisuri ale mucoasei gingivale."},{"id":"D","text":"Se constată prezența constantă a ulcerațiilor pe papilele interdentare."},{"id":"E","text":"Mucoasa orală prezintă arii extinse de hiperplazie generalizată."}],"correct":["A","B","C"],"pages":[333],"source":"set-2"},{"id":"set2-GJBVdCQp","fingerprint":"d275406935f44cf5","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt situațiile etiologice care pot determina apariția gingivitei și gingivostomatitei de menopauză?","options":[{"id":"A","text":"Erupția dentară din perioada de tranziție."},{"id":"B","text":"Histerectomiile."},{"id":"C","text":"Sterilizările prin iradierea unor tumori maligne."},{"id":"D","text":"Menopauza normală, fiziologică."},{"id":"E","text":"Ovarectomiile."}],"correct":["B","C","D","E"],"pages":[332],"source":"set-2"},{"id":"set2-RcQEmCOz","fingerprint":"e98d0eb913d6c9e8","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este rolul etiopatogenic al diabetului zaharat în dezvoltarea îmbolnăvirilor gingiei și ale parodonțiului profund?","options":[{"id":"A","text":"Inițiază formarea directă a tartrului subgingival prin hiperglicemie salivară."},{"id":"B","text":"Constituie cauza directă și unică a distrucției țesuturilor de susținere dentară."},{"id":"C","text":"Induce o reacție autoimună mediată celular, localizată exclusiv la nivelul epiteliului gingival."},{"id":"D","text":"Secretă compuși acizi care lizează în mod direct osul alveolar."},{"id":"E","text":"Favorizează un răspuns modificat de apărare din partea structurilor parodontale față de placa bacteriană."}],"correct":["E"],"pages":[333],"source":"set-2"},{"id":"set2-C3TNzldI","fingerprint":"f171a210ef4d5879","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt principalele microorganisme identificate în șanțul gingival în cazul gingivitelor asociate cu diabetul zaharat insulino-dependent?","options":[{"id":"A","text":"Porphyromonas gingivalis"},{"id":"B","text":"Fusobacterium"},{"id":"C","text":"Veillonela parvula"},{"id":"D","text":"Aggregatibacter actinomycetemcomitans"},{"id":"E","text":"Specii de Streptococ"}],"correct":["B","C","E"],"pages":[333],"source":"set-2"},{"id":"set2-0uSfr-EH","fingerprint":"8806bb12398f6dd1","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce modificări tisulare și vasculare se produc la nivel gingival sub influența diabetului zaharat?","options":[{"id":"A","text":"Îngroșarea membranei bazale dintre epiteliu și corion"},{"id":"B","text":"Creșterea rezistenței peretelui vascular cu hiperplazie endotelială protectoare"},{"id":"C","text":"Acumularea de compuși intermediari cu acțiune toxică prin acidoză tisulară"},{"id":"D","text":"Subțierea marcată a corionului subiacent cu atrofie vasculară masivă"},{"id":"E","text":"Reducerea lumenului capilarelor și arteriolelor"}],"correct":["A","C","E"],"pages":[333],"source":"set-2"},{"id":"set2-q33Jb9VO","fingerprint":"c135c2fa431f5570","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt semnele clinice întâlnite la nivel gingival pe parcursul evoluției diabetului zaharat?","options":[{"id":"A","text":"Polipi gingivali sesili sau pediculați"},{"id":"B","text":"Consistență fermă, fibroasă a papilelor gingivale"},{"id":"C","text":"Prezența pungilor parodontale adevărate, adânci"},{"id":"D","text":"Hiperplazie gingivală generalizată, de tip polipoidal"},{"id":"E","text":"Culoare roșu-cărămiziu sau roșu-violaceu în fazele avansate de stază"}],"correct":["A","D","E"],"pages":[333],"source":"set-2"},{"id":"set2-VlzBuGyD","fingerprint":"705dbdb373704c01","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Prin ce mecanism se instalează ușoara mobilitate patologică a dinților în cadrul modificărilor gingivale asociate diabetului zaharat?","options":[{"id":"A","text":"Prin resorbția osoasă verticală masivă la nivelul crestei alveolare."},{"id":"B","text":"Prin retracția gingivală apărută consecutiv hiperplaziei de tip fibromatos."},{"id":"C","text":"Prin distrucția directă a fibrelor ligamentului parodontal de către glicozilarea avansată."},{"id":"D","text":"Prin edemul inflamator instalat la nivelul parodonțiului."},{"id":"E","text":"Prin presiunea exercitată de pungile parodontale adevărate asupra osului subiacent."}],"correct":["D"],"pages":[333],"source":"set-2"},{"id":"set2-D750XiDL","fingerprint":"4c3f2dccfd8f7fb2","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt categoriile de pacienți sau condițiile care predispun la apariția scorbutului ca formă severă a deficienței de vitamina C?","options":[{"id":"A","text":"Femeile aflate în ultimul trimestru de sarcină, prin hiperplazie hormonală."},{"id":"B","text":"Adolescenții în perioada erupției dentare active."},{"id":"C","text":"Copiii în primul an de viață, afecțiunea purtând denumirea de boala Moeller-Barlow."},{"id":"D","text":"Persoanele cu alcoolism cronic."},{"id":"E","text":"Vârstnicii care prezintă deficiențe de nutriție."}],"correct":["C","D","E"],"pages":[333],"source":"set-2"},{"id":"set2-DyNiVYp-","fingerprint":"82c17728dc59d1e2","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce manifestări clinice și simptome sunt caracteristice gingivitei hiperplazice din hipovitaminoza C?","options":[{"id":"A","text":"Hipersalivație compensatorie abundentă."},{"id":"B","text":"Hiperplazie gingivală asociată cu ulcerații."},{"id":"C","text":"Sângerări gingivale produse la cele mai mici atingeri."},{"id":"D","text":"Formarea de pungi false."},{"id":"E","text":"Mobilitate dentară patologică indusă de resorbția osoasă masivă."}],"correct":["B","C","D"],"pages":[334],"source":"set-2"},{"id":"set2-8UIChDQl","fingerprint":"d4637a11d6022c84","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este impactul plăcii bacteriene și al igienei bucale asupra evoluției clinice a hipovitaminozei C la nivel parodontal?","options":[{"id":"A","text":"În prezența unei igiene bucale bune, modificările distructive ale gingiei și parodonțiului sunt reduse sau nu se manifestă clinic."},{"id":"B","text":"Acumularea de placă bacteriană stimulează cicatrizarea rapidă a ulcerațiilor gingivale."},{"id":"C","text":"Igiena bucală deficitară transformă pungile parodontale adevărate în pungi false."},{"id":"D","text":"Gingivita hiperplazică este declanșată exclusiv de deficitul de vitamina C, independent de existența plăcii bacteriene."},{"id":"E","text":"Deficitul de vitamina C la pacienții cu igienă bună duce inexorabil la avulsia extrem de dureroasă a dinților."}],"correct":["A"],"pages":[334],"source":"set-2"},{"id":"set2-juU37VRN","fingerprint":"9fcce920f7e85e63","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Ce consecință clinică are prezența plăcii bacteriene asupra tabloului simptomatic în gingivita hiperplazică din hipovitaminoza C?","options":[{"id":"A","text":"Scăderea mobilității patologice prin resorbția edemului gingival subiacent."},{"id":"B","text":"Declanșarea hiperesteziei dentinare generalizate însoțite de trismus."},{"id":"C","text":"Sclerozarea țesutului gingival cu oprirea definitivă a sângerărilor la atingere."},{"id":"D","text":"Transformarea pungilor false în eroziuni epiteliale superficiale strict asimptomatice."},{"id":"E","text":"Apariția pungilor parodontale adevărate și avulsia dentară, de obicei puțin sau deloc dureroasă."}],"correct":["E"],"pages":[334],"source":"set-2"},{"id":"set2-LcRIIWIg","fingerprint":"4583cbee2d8de644","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este mecanismul fiziopatologic implicat în apariția precoce a gingivoragiilor în cadrul gingivitei hiperplazice din leucemie?","options":[{"id":"A","text":"Hiperplazia extensivă a țesutului gingival"},{"id":"B","text":"Granulocitopenia"},{"id":"C","text":"Infiltrarea leucemică a țesuturilor subcutanate"},{"id":"D","text":"Formarea de false membrane la nivelul marginii gingivale libere"},{"id":"E","text":"Trombocitopenia leucemică"}],"correct":["E"],"pages":[334],"source":"set-2"},{"id":"set2-Zec6ggXy","fingerprint":"29cf558cf3edc82a","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la manifestările clinice ale gingivitei hiperplazice asociate leucemiei?","options":[{"id":"A","text":"Gingia afectată prezintă o colorație roșie-violacee, cianotică."},{"id":"B","text":"Afecțiunea se produce cel mai frecvent în leucemiile cronice."},{"id":"C","text":"La nivelul mucoasei bucale se observă frecvent peteșii și infiltrate leucemice."},{"id":"D","text":"Ulcerațiile gingivale sunt frecvent suprainfectate pe fondul granulocitopeniei."},{"id":"E","text":"Hiperplazia gingivală este strict localizată și nu depășește treimea cervicală a dintelui."}],"correct":["A","C","D"],"pages":[334],"source":"set-2"},{"id":"set2-oO8zR_cP","fingerprint":"6faa07eec8edccfb","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"În ce regiuni anatomice sunt localizate frecvent ulcerațiile specifice manifestărilor bucale din leucemie?","options":[{"id":"A","text":"Pe suprafața dorsală a limbii"},{"id":"B","text":"În zona mucoasei jugale din dreptul planului de ocluzie"},{"id":"C","text":"La nivelul palatului"},{"id":"D","text":"Pe suprafața gingivală"},{"id":"E","text":"La nivelul planșeului bucal"}],"correct":["B","C","D"],"pages":[334],"source":"set-2"},{"id":"set2-0SER1xkz","fingerprint":"ff370da049c7b51e","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele specii bacteriene sunt implicate în etiologia gingivitei și gingivostomatitei acute ulcero-necrotice?","options":[{"id":"A","text":"Treponema vincenti"},{"id":"B","text":"Streptococcus mutans"},{"id":"C","text":"Porphyromonas gingivalis"},{"id":"D","text":"Fusobacterium nucleatum"},{"id":"E","text":"Prevotella intermedia"}],"correct":["A","C","D","E"],"pages":[334],"source":"set-2"},{"id":"set2-l-mklgeC","fingerprint":"fea1e05ff338b93f","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt factorii favorizanți implicați în patogenia gingivitei și gingivostomatitei acute ulcero-necrotice?","options":[{"id":"A","text":"Deficitul de vitamina D și vitamina E"},{"id":"B","text":"Pericoronaritele"},{"id":"C","text":"Obezitatea de gradul III"},{"id":"D","text":"Stresul psihosomatic"},{"id":"E","text":"Fumatul excesiv"}],"correct":["B","D","E"],"pages":[334],"source":"set-2"},{"id":"set2-vuuHNOI9","fingerprint":"4d86518094887294","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este semnul patognomonic în gingivita și gingivostomatita acută ulcero-necrotică?","options":[{"id":"A","text":"Prezența leziunilor ulcerative pe mucoasa jugală și linguală"},{"id":"B","text":"Durerile iradiate în oasele maxilare la contactul cu alimente fierbinți"},{"id":"C","text":"Halena intensă și hipersalivația vâscoasă"},{"id":"D","text":"Delimitarea la bază a gingiei printr-un lizereu albastru-violaceu"},{"id":"E","text":"Ulcerația crateriformă la vârful papilelor interdentare („aspect decapitat”), extinsă la marginea gingivală liberă"}],"correct":["E"],"pages":[335],"source":"set-2"},{"id":"set2-PoliPCz4","fingerprint":"edb13f182ec907c0","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele manifestări aparțin simptomatologiei subiective a gingivitei și gingivostomatitei acute ulcero-necrotice?","options":[{"id":"A","text":"Senzația de gust metalic și alterat"},{"id":"B","text":"Dureri intense la atingerea gingiei"},{"id":"C","text":"Limitarea deschiderii gurii prin trismus"},{"id":"D","text":"Adenopatia regională"},{"id":"E","text":"Rigiditatea feței"}],"correct":["A","B","C"],"pages":[335],"source":"set-2"},{"id":"set2-JBfIYDV_","fingerprint":"d93165aef8e6a29b","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce elemente caracterizează alterarea stării generale a unui pacient cu gingivostomatită acută ulcero-necrotică?","options":[{"id":"A","text":"Febră cuprinsă între 38,5 și 39º C"},{"id":"B","text":"Bradicardie marcată și episoade de sincopă"},{"id":"C","text":"Tulburări de tranzit gastrointestinal"},{"id":"D","text":"Stare de hiperactivitate psihomotorie"},{"id":"E","text":"Astenie, adinamie și inapetență"}],"correct":["A","C","E"],"pages":[335],"source":"set-2"},{"id":"set2-iGy8DjuF","fingerprint":"c896054f520e3180","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt principalele medicamente implicate în producerea hiperplaziilor gingivale?","options":[{"id":"A","text":"Hidantoina"},{"id":"B","text":"Diureticele de ansă"},{"id":"C","text":"Corticosteroizii"},{"id":"D","text":"Antagoniștii de calciu"},{"id":"E","text":"Ciclosporinele"}],"correct":["A","D","E"],"pages":[335],"source":"set-2"},{"id":"set2-djXQkQlj","fingerprint":"92fee86fc3428868","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele caracteristici clinice descriu hiperplazia gingivală hidantoinică necomplicată de inflamația supraadăugată?","options":[{"id":"A","text":"Afectarea severă a zonei de gingie fixă"},{"id":"B","text":"Culoarea roșu-violaceu și sângerarea spontană"},{"id":"C","text":"Localizarea masivă pe versantul oral"},{"id":"D","text":"Aspectul lobulat și consistența fermă"},{"id":"E","text":"Prezența unui șanț situat la baza hiperplaziei papilelor"}],"correct":["D","E"],"pages":[335],"source":"set-2"},{"id":"set2-ONKQg6hm","fingerprint":"3d0af6e6859f24aa","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este principalul criteriu clinic care diferențiază hiperplazia gingivală hidantoinică de hiperplazia gingivală idiopatică?","options":[{"id":"A","text":"Zona de gingie fixă este, de obicei, mai puțin hiperplazică."},{"id":"B","text":"Hiperplazia afectează în mod egal și simetric ambele versante alveolare."},{"id":"C","text":"Debutul leziunii se face exclusiv prin apariția unui șanț la limita cu mucoasa alveolară."},{"id":"D","text":"Leziunea sângerează spontan la cele mai mici atingeri."},{"id":"E","text":"Leziunea apare exclusiv în prezența tartrului și a plăcii bacteriene abundente."}],"correct":["A"],"pages":[335],"source":"set-2"},{"id":"set2-izbzFmgh","fingerprint":"61dc200a3fd9d3a0","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt afirmațiile adevărate cu privire la influența plăcii bacteriene asupra hiperplaziei gingivale hidantoinice?","options":[{"id":"A","text":"Prezența plăcii bacteriene determină supraadăugarea inflamației bacteriene."},{"id":"B","text":"Hiperplazia hidantoinică se poate produce chiar și în absența plăcii bacteriene."},{"id":"C","text":"Inflamația bacteriană are ca efect accentuarea hipertrofiei și a hiperplaziei gingivale."},{"id":"D","text":"Placa bacteriană împiedică retragerea leziunii de pe versantul oral."},{"id":"E","text":"Acumularea de tartru este obligatorie pentru declanșarea leziunilor incipiente."}],"correct":["A","B","C"],"pages":[335],"source":"set-2"},{"id":"set2-lWr53Muv","fingerprint":"4c18dd79d7c78fbf","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt manifestările clinice și evolutive specifice ce definesc hiperplazia gingivală hidantoinică?","options":[{"id":"A","text":"Localizarea leziunilor predomină pe versantul vestibular."},{"id":"B","text":"În fazele de debut, marginea gingivală acoperă o suprafață foarte mare a coroanei dentare."},{"id":"C","text":"Leziunile se localizează predominant oral, pe fondul iritației mucoasei de către papilele gustative."},{"id":"D","text":"Se poate constata reducerea spontană a hiperplaziei la câteva luni după întreruperea administrării medicamentului."},{"id":"E","text":"În stadiul inițial, formațiunile au dimensiuni mici, de forma unor mărgele ale papilelor interdentare."}],"correct":["A","D","E"],"pages":[335],"source":"set-2"},{"id":"set2-jN16QpSn","fingerprint":"13b838fba70d197b","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt caracteristicile hiperplaziei gingivale induse de tratamentul cu ciclosporine?","options":[{"id":"A","text":"Consistența gingiei devine moale și depresibilă odată cu creșterea sa în volum."},{"id":"B","text":"Gingia hiperplazică capătă un aspect clinic marcat de o colorație roz și o consistență fermă."},{"id":"C","text":"Gingia prezintă o tendință redusă de sângerare, provenită din inflamația septică bacteriană supraadăugată."},{"id":"D","text":"Culoarea gingiei variază de la roșu congestiv până la roșu închis, prezentând frecvent zone ulcerate."},{"id":"E","text":"Incidența acestei hiperplazii la bolnavii tratați cu agenți imunosupresori este de aproximativ 30%."}],"correct":["B","C","E"],"pages":[336],"source":"set-2"},{"id":"set2-YMng4zHd","fingerprint":"442e20e471eee263","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt efectele terapeutice obținute în urma administrării substanțelor care inhibă fluxul ionilor de Ca²⁺ prin canalele lente membranare?","options":[{"id":"A","text":"Efect antianginos rezultat din inhibarea contracției miocardului."},{"id":"B","text":"Efect antiaritmic și bradicardic obținut prin stimularea funcției miocardului specific generator de potențiale."},{"id":"C","text":"Prevenirea rejecției de organe transplantate printr-un mecanism celular imunosupresor direct."},{"id":"D","text":"Deprimarea funcției nodulului sinusal și a nodulului atrioventricular."},{"id":"E","text":"Relaxarea mușchilor netezi, în special a celor vasculari, generând un efect vasodilatator."}],"correct":["A","D","E"],"pages":[336],"source":"set-2"},{"id":"set2-hrBVSFkx","fingerprint":"b6852af5e24023d7","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce trăsături descriu aspectul clinic al hiperplaziei gingivale la pacienții aflați sub tratament cu antagoniști de calciu?","options":[{"id":"A","text":"La un număr restrâns de pacienți cu igienă bucală optimă, se poate dezvolta o formă nodulară de hiperplazie."},{"id":"B","text":"Volumul hiperplaziei depinde de predispoziția genetică, independent de doza de medicament administrată."},{"id":"C","text":"Consistența gingiei este inițial fermă, dar se reduce în timp, devenind moale și depresibilă pe măsură ce crește în volum."},{"id":"D","text":"Gingia hiperplazică este frecvent decolabilă de coroana dintelui, evidențiind depozite de țesuturi sfacelate și exudat purulent."},{"id":"E","text":"Leziunile au un caracter strict localizat, fiind limitate exclusiv la nivelul fețelor linguale ale dinților."}],"correct":["A","C","D"],"pages":[336],"source":"set-2"},{"id":"set2-LILlAlGN","fingerprint":"0baf13d1beab5274","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este atitudinea terapeutică recomandată medicului stomatolog în fața unui pacient cu o hiperplazie gingivală dezvoltată în cursul tratamentului cronic cu antagoniști de calciu?","options":[{"id":"A","text":"Păstrarea tratamentului general instituit pentru afecțiunea de fond și asocierea unei terapii locale stomatologice adecvate."},{"id":"B","text":"Ajustarea directă a dozelor de medicație antianginoasă la niveluri subterapeutice pentru a opri sângerarea parodontală."},{"id":"C","text":"Îndepărtarea placardelor fibrinoase concomitent cu aplicarea antibioticelor sistemice ca monoterapie absolută."},{"id":"D","text":"Înlocuirea promptă a antagonistului de calciu cu un agent imunosupresor care prezintă un risc hiperplazic mai scăzut."},{"id":"E","text":"Recomandarea suprimării imediate a tratamentului cardiovascular pentru a induce o regresie spontană a țesutului hiperplaziat."}],"correct":["A"],"pages":[336],"source":"set-2"},{"id":"set2-BJgH2xrE","fingerprint":"88af34340ea17d04","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Prin ce particularități clinice sau epidemiologice se diferențiază hiperplaziile gingivale induse de diferitele clase de medicamente studiate?","options":[{"id":"A","text":"Hiperplazia secundară antagoniștilor de calciu se prezintă sub forma unei gingii de culoare roșie, în timp ce tratamentul cu ciclosporine induce o gingie de colorație roz."},{"id":"B","text":"Forma nodulară fermă, netedă, reprezintă principalul aspect clinic al hiperplaziei induse de antagoniștii de calciu la marea majoritate a bolnavilor."},{"id":"C","text":"Topografic, hiperplazia produsă de antagoniștii de calciu este situată doar la mandibulă, în vreme ce formele asociate ciclosporinelor sunt maxilare."},{"id":"D","text":"Prevalența apariției hiperplaziei gingivale atinge un nivel de aproximativ 30% în rândul pacienților la care se utilizează ciclosporine."},{"id":"E","text":"Sângerarea gingivală manifestată sub medicația cu ciclosporine are ca punct de plecare inflamația septică bacteriană supraadăugată."}],"correct":["A","E"],"pages":[336],"source":"set-2"},{"id":"set2-LdlUHRsh","fingerprint":"b93d64a829cef1c1","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele afirmații descriu etiologia și caracteristicile histopatologice ale gingivitei alergice?","options":[{"id":"A","text":"Etiologia sa principală este reprezentată de acumularea plăcii bacteriene în șanțul gingival."},{"id":"B","text":"Afecțiunea este denumită frecvent gingivită cu eozinofile, datorită naturii sale alergice."},{"id":"C","text":"Se poate declanșa ca urmare a unei reacții la componente din paste de dinți, ape de gură sau dentifrice."},{"id":"D","text":"Examenul histopatologic evidențiază în corion un bogat infiltrat plasmocitar."},{"id":"E","text":"Extractul de Sapota Zapotilla reprezintă un potențial factor declanșator al afecțiunii."}],"correct":["C","D","E"],"pages":[336,337],"source":"set-2"},{"id":"set2-C5dBG_IA","fingerprint":"f7213f45f353432a","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt semnele clinice specifice prezente în tabloul simptomatologic al gingivitei alergice?","options":[{"id":"A","text":"Consistența țesutului gingival este redusă, devenind moale și friabilă."},{"id":"B","text":"Afecțiunea se asociază frecvent cu manifestări clinice de cheilită și glosită."},{"id":"C","text":"Sângerarea se declanșează exclusiv în timpul sondării profunde a pungilor parodontale."},{"id":"D","text":"Culoarea roșie intensă cuprinde papilele interdentare, marginea liberă și gingia fixă, dispărând brusc la nivelul joncțiunii mucogingivale."},{"id":"E","text":"Tumefacția gingivală asociază o creștere de volum, având un aspect neted și intens lucios."}],"correct":["A","B","D"],"pages":[336,337],"source":"set-2"},{"id":"set2-jD8oT965","fingerprint":"39e94f7efa05a3a5","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este caracteristica definitorie a gingivitelor neinduse de placa bacteriană și prin ce metodă clinică se confirmă etiologia alergenă a leziunilor?","options":[{"id":"A","text":"Apar exclusiv în prezența plăcii bacteriene și cedează rapid la instruirea pacientului privind igiena orală."},{"id":"B","text":"Sunt caracterizate de un eritem gingival care se extinde invariabil la nivelul mucoasei geniene, confirmând toxicitatea materialului utilizat."},{"id":"C","text":"Etiologia este confirmată prin persistența simptomatologiei inflamatorii la mai mult de o lună după sistarea folosirii produselor incriminate."},{"id":"D","text":"Nu se remit de obicei după îndepărtarea plăcii bacteriene, iar rolul alergen se confirmă prin întreruperea folosirii produselor implicate și dispariția leziunilor."},{"id":"E","text":"Sunt influențate de periajul agresiv, iar diagnosticul se confirmă prin evaluarea radiologică a nivelului osos alveolar."}],"correct":["D"],"pages":[336,337],"source":"set-2"},{"id":"set2-_jiiIvSf","fingerprint":"7e19f02ecb5ad183","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este aspectul caracteristic și modificarea epitelială principală observată în gingivitele descuamative?","options":[{"id":"A","text":"Ulcerații profunde acoperite de membrane false alb-gălbui, fără implicarea keratinei."},{"id":"B","text":"Hiperplazie epitelială marcată cu un strat gros de keratină."},{"id":"C","text":"Hiperkeratoză difuză cu leziuni papilomatoase extinse."},{"id":"D","text":"Manifestări de tip vezicular sau bulos, asociate cu atrofie epitelială și keratină slab reprezentată sau absentă."},{"id":"E","text":"Formare de noduli fibroși cu acantoză epitelială severă."}],"correct":["D"],"pages":[337],"source":"set-2"},{"id":"set2-WH9iQvG4","fingerprint":"ee519471bf5e4de2","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"În care dintre următoarele circumstanțe și afecțiuni sistemice pot fi observate gingivitele descuamative?","options":[{"id":"A","text":"Infecții bacteriene acute."},{"id":"B","text":"Pemfigus vulgar."},{"id":"C","text":"Infecții acute virale recurente."},{"id":"D","text":"Post-histerectomii, la menopauză sau postmenopauză."},{"id":"E","text":"Lichen plan vezicular sau bulos cu leziuni erozive."}],"correct":["B","D","E"],"pages":[337],"source":"set-2"},{"id":"set2-5F1fK4Ng","fingerprint":"e04d8a318932d30b","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Administrarea căror medicamente este incriminată în apariția gingivitelor descuamative prin reacții de hipersensibilizare?","options":[{"id":"A","text":"Anticoncepționale orale."},{"id":"B","text":"Barbiturice."},{"id":"C","text":"Fenolftaleină din laxative."},{"id":"D","text":"Săruri de bismut."},{"id":"E","text":"Blocante ale canalelor de calciu."}],"correct":["B","C","D"],"pages":[337],"source":"set-2"},{"id":"set2-4TWCdt0R","fingerprint":"d3cd1bfeedb03b26","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt caracteristicile leziunilor primare și evoluția acestora la nivelul mucoasei gingivale și orale în gingivitele descuamative?","options":[{"id":"A","text":"Leziunile inițiale evoluează frecvent către papiloame hiperkeratozice."},{"id":"B","text":"Spargerea veziculelor și a bulelor dă naștere unor leziuni de tip eroziv și ulcerat."},{"id":"C","text":"Leziunea de bază veziculară are în general dimensiuni de până la 5 mm diametru."},{"id":"D","text":"Bulele prezintă dimensiuni care pot atinge câțiva centimetri."},{"id":"E","text":"Veziculele rămân intacte perioade îndelungate pe suprafața mucoasei."}],"correct":["B","C","D"],"pages":[337],"source":"set-2"},{"id":"set2-8rtpp39V","fingerprint":"31d505c4a46bf3c1","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este evoluția imediată a leziunilor buloase apărute la nivelul mucoasei gingivale și orale în cadrul gingivitelor descuamative?","options":[{"id":"A","text":"Generează o reacție de hipersensibilizare cu formare de cicatrici cheloide."},{"id":"B","text":"Se vindecă rămânând sub formă de zone de atrofie epitelială stabilă, fără ulcerație."},{"id":"C","text":"Confluează formând plăci hiperkeratozice indurate."},{"id":"D","text":"Se transformă treptat în macule pigmentare persistente."},{"id":"E","text":"Se sparg în scurt timp și generează leziuni de tip eroziv și ulcerat."}],"correct":["E"],"pages":[337],"source":"set-2"},{"id":"set2-LedZ6d3Z","fingerprint":"0e046485672f125f","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele afirmații referitoare la caracteristicile temporale și evolutive ale gingivostomatitei herpetice sunt adevărate?","options":[{"id":"A","text":"Evoluția bolii se desfășoară în pusee de intensitate din ce în ce mai redusă."},{"id":"B","text":"Perioada de incubație este scurtă, cuprinsă între 48 și 72 de ore."},{"id":"C","text":"Vindecarea totală a afecțiunii se obține după aproximativ două săptămâni."},{"id":"D","text":"Boala debutează insidios, pe parcursul a câtorva zile, prin apariția de macule eritematoase."},{"id":"E","text":"Afecțiunea prezintă o incidență crescută și o evoluție mai severă la pacienții vârstnici."}],"correct":["A","B","C"],"pages":[337],"source":"set-2"},{"id":"set2-GCJWiIV6","fingerprint":"ab221fc9cd6c2ab8","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt caracteristicile leziunilor specifice apărute pe mucoasa bucală în cadrul gingivostomatitei herpetice?","options":[{"id":"A","text":"Suprainfectarea ulcerațiilor de pe mucoasa bucală declanșează o simptomatologie dureroasă."},{"id":"B","text":"Ulcerațiile rezultate în urma spargerii veziculelor sunt superficiale și au o colorație galben-gri."},{"id":"C","text":"Veziculele rămân intacte timp de mai multe zile, transformându-se direct în cruste groase și aderente."},{"id":"D","text":"Leziunile sunt înconjurate de un halou inflamator de culoare roșie."},{"id":"E","text":"Veziculele se sparg într-un interval scurt, de câteva ore de la apariție."}],"correct":["A","B","D","E"],"pages":[337],"source":"set-2"},{"id":"set2-tKECsXcm","fingerprint":"7c5670c61c701edb","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"La nivelul cărei structuri anatomice supraviețuiește virusul herpetic în stare latentă, facilitând descinderea sa pe calea nervilor în condiții favorizante?","options":[{"id":"A","text":"Ganglionul geniculat."},{"id":"B","text":"Mucoasa istmului faringian."},{"id":"C","text":"Ganglionii limfatici loco-regionali."},{"id":"D","text":"Ganglionul nervos sfenopalatin."},{"id":"E","text":"Ganglionul nervos Gasser."}],"correct":["E"],"pages":[337],"source":"set-2"},{"id":"set2-TbZ8bsue","fingerprint":"6bac7e82cce65212","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre factorii de mai jos reprezintă condiții favorizante capabile să declanșeze recidiva infecției cu virusul herpetic?","options":[{"id":"A","text":"Traumatismele și intervențiile precum extracțiile dentare."},{"id":"B","text":"Vârsta înaintată, fenomen însoțit de creșterea frecvenței leziunilor herpetice."},{"id":"C","text":"Fluctuațiile asociate ciclului menstrual."},{"id":"D","text":"Expunerea la radiațiile solare."},{"id":"E","text":"Afecțiunile generale gastrointestinale, gripa și hepatita epidemică."}],"correct":["A","C","D","E"],"pages":[338],"source":"set-2"},{"id":"set2-gYmBI-4e","fingerprint":"14c087d5baf670e9","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care este aspectul morfologic caracteristic al ulcerației apărute consecutiv spargerii veziculelor grupate în gingivostomatita herpetică?","options":[{"id":"A","text":"Ulcerație profundă, cu margini intens indurate și pat necrotic."},{"id":"B","text":"Ulcerație izolată, prezentând un halou galben-gri lipsit de inflamație periferică."},{"id":"C","text":"Ulcerație confluentă, mărginită de un contur policiclic."},{"id":"D","text":"Ulcerație strict liniară, dispusă cu precădere de-a lungul joncțiunii muco-gingivale."},{"id":"E","text":"Ulcerație cu evoluție blândă, nedureroasă, vindecabilă în câteva ore."}],"correct":["C"],"pages":[337],"source":"set-2"},{"id":"set2-x4qNmRjO","fingerprint":"504bffa557bac926","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următorii factori sunt recunoscuți ca favorizanți cu acțiune generală pentru dezvoltarea gingivostomatitei aftoase recidivante?","options":[{"id":"A","text":"Erupția dentară"},{"id":"B","text":"Hipertiroidismul"},{"id":"C","text":"Afecțiunile gastrointestinale"},{"id":"D","text":"Consumul de dulciuri cu alune, miere sau ciocolată"},{"id":"E","text":"Sarcina"}],"correct":["B","C","E"],"pages":[338],"source":"set-2"},{"id":"set2-tJwgoA5D","fingerprint":"d97c70d1f7496676","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce caracteristici clinice și evolutive sunt asociate leziunilor din gingivostomatita aftoasă recidivantă?","options":[{"id":"A","text":"Ulcerația tipică se prezintă cu o colorație alb-gălbuie, margini netede bine conturate și un halou eritematos periferic."},{"id":"B","text":"Aftoza bipolară este definită exclusiv de apariția simultană a leziunilor pe mucoasa jugală și linguală."},{"id":"C","text":"Aftele mici, cu diametrul de 0,2-1 cm, persistă mai multe săptămâni și sunt urmate constant de cicatrice."},{"id":"D","text":"Leziunea inițială este o veziculă cu o durată scurtă de viață care lasă în urmă o ulcerație superficială."},{"id":"E","text":"Aftele de dimensiuni mari, având un diametru de 1-3 cm, se vindecă într-un interval de 7-10 zile fără formarea de cicatrice."}],"correct":["A","D"],"pages":[338],"source":"set-2"},{"id":"set2-IauVu_fp","fingerprint":"d56a2b820d8aecb9","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt semnele și simptomele regăsite în tabloul clinic al gingivostomatitei aftoase recidivante?","options":[{"id":"A","text":"Bolnavii prezintă febră ușoară, curbatură, inapetență și insomnie."},{"id":"B","text":"Adenopatia loco-regională însoțește constant manifestările bolii."},{"id":"C","text":"Manifestările locale se pot asocia frecvent cu trismus și hipersalivație."},{"id":"D","text":"Durerile dispar pe parcursul mișcărilor de masticație și deglutiție."},{"id":"E","text":"Starea generală este profund alterată, prezentând febră înaltă și letargie."}],"correct":["A","B","C"],"pages":[338],"source":"set-2"},{"id":"set2-LmLJupGL","fingerprint":"694a1eb729c3bf58","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Prin ce elemente se stabilește diagnosticul pozitiv și cel diferențial în cazul gingivostomatitei aftoase recidivante?","options":[{"id":"A","text":"Diagnosticul pozitiv utilizează un test terapeutic bazat pe albirea ulcerației la contactul cu soluția de nitrat de argint 30%."},{"id":"B","text":"Prezența leziunilor în zonele cutaneo-mucoase constituie un criteriu obligatoriu pentru confirmarea gingivostomatitei aftoase recidivante."},{"id":"C","text":"Aspectul clinic caracteristic al ulcerațiilor și prezența durerilor intense constituie fundamentul diagnosticului pozitiv."},{"id":"D","text":"Gingivostomatita herpetică se caracterizează clinic printr-o intensitate mai redusă a sindromului algic față de gingivostomatita aftoasă."},{"id":"E","text":"Afecțiunea are o rată de incidență crescută la copii, în comparație cu adulții, facilitând diagnosticul diferențial."}],"correct":["A","C","D"],"pages":[338],"source":"set-2"},{"id":"set2-OXL8VD6c","fingerprint":"1e6a4e5f70b5ea9d","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre afirmațiile următoare privitoare la etiologia, incidența și evoluția inițială a gingivostomatitei aftoase recidivante sunt valabile?","options":[{"id":"A","text":"Etiologia afecțiunii este complet identificată, indicând un mecanism direct de origine virală."},{"id":"B","text":"În dezvoltarea bolii par a fi implicate mecanisme imunopatologice complexe, în ciuda etiologiei neprecizate."},{"id":"C","text":"Recidivele bolii apar într-un tipar previzibil și au loc strict la intervale regulate de șase luni."},{"id":"D","text":"Evoluția inițială pe mucoasa bucală este marcată de o veziculă limitată la o durată de viață de câteva ore."},{"id":"E","text":"Patologia prezintă o incidență dominantă în rândul copiilor și se dezvoltă extrem de rar la adulți."}],"correct":["B","D"],"pages":[338],"source":"set-2"},{"id":"set2-GsBWbVey","fingerprint":"fa7e46cde9d79149","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care dintre următoarele condiții sistemice favorizează transformarea Candidei albicans într-un microorganism patogen și agresiv la nivelul epiteliului gingival?","options":[{"id":"A","text":"Sarcina și utilizarea contraceptivelor"},{"id":"B","text":"Hipertiroidismul"},{"id":"C","text":"Hipotiroidismul"},{"id":"D","text":"Diabetul"},{"id":"E","text":"Administrarea dozelor mici de tetraciclină pe perioade scurte"}],"correct":["A","C","D"],"pages":[338],"source":"set-2"},{"id":"set2-tLgBT0ew","fingerprint":"90fe8b78a3b3ce61","chapterId":"set-2","subchapterId":"set2-4.05","type":"CS","text":"Care afirmație descrie comportamentul și efectele tetraciclinei administrate în doze mici (0,250 g - 0,500 g/zi) în contextul afecțiunilor gingivo-parodontale?","options":[{"id":"A","text":"Induce invariabil apariția unui sindrom de imunodeficiență locală."},{"id":"B","text":"Se concentrează în lichidul șanțului gingival de două-trei ori mai mult decât în sânge."},{"id":"C","text":"Constituie cauza principală a transformării imediate a Candidei albicans într-un microorganism distructiv."},{"id":"D","text":"Se concentrează în patul vascular de două-trei ori mai mult comparativ cu lichidul șanțului gingival."},{"id":"E","text":"Are efecte exclusiv distructive asupra corionului gingival."}],"correct":["B"],"pages":[339],"source":"set-2"},{"id":"set2-LsJB0Dg0","fingerprint":"f8afce9ba58c24c8","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Care sunt semnele clinice obiective caracteristice leziunilor candidozice la copii?","options":[{"id":"A","text":"Leziunile izolate inițial devin confluente pe un fond eritematos generalizat."},{"id":"B","text":"Puncte sângerânde apărute în urma desprinderii depozitelor prin raclare energică."},{"id":"C","text":"Detașarea spontană a depozitelor miceliene lăsând o mucoasă intactă și palidă."},{"id":"D","text":"Prezența unor depozite de culoare alb-crem care imită laptele coagulat."},{"id":"E","text":"Atrofia papilelor filiforme ale limbii, conferind un aspect neted și lucios."}],"correct":["A","B","D"],"pages":[339],"source":"set-2"},{"id":"set2-iPLW2IMl","fingerprint":"f87b89b9f795e6cd","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce forme clinice și modificări obiective se întâlnesc în gingivostomatita de cauză micotică la pacienții adulți?","options":[{"id":"A","text":"Atrofia papilelor filiforme ale limbii care capătă un aspect neted și lucios."},{"id":"B","text":"Plăci pseudomembranoase negricioase suprapuse pe un fond tisular purulent."},{"id":"C","text":"Sialoree abundentă cu hipertrofia papilelor circumvalate."},{"id":"D","text":"Fisuri și ulcerații localizate la nivelul comisurii buzelor, urmate de formarea de cruste."},{"id":"E","text":"Hiperkeratoza epiteliului gingival și lingual cu apariția unor plăci albe aderente."}],"correct":["A","D","E"],"pages":[339],"source":"set-2"},{"id":"set2-xxOjGkab","fingerprint":"a6486f3d3ea5a0c0","chapterId":"set-2","subchapterId":"set2-4.05","type":"CM","text":"Ce simptome de ordin subiectiv pot acompania manifestările gingivostomatitei micotice?","options":[{"id":"A","text":"Apariția unor fisuri dureroase la nivelul mucoasei bucale."},{"id":"B","text":"Dificultatea de a purta proteze dentare mobile."},{"id":"C","text":"Senzații dureroase provocate de contactul cu alimente ce au un pH acid."},{"id":"D","text":"Anestezia completă a zonelor eritematoase de pe mucoasa jugală."},{"id":"E","text":"Senzație de arsură cu localizare esofagiană post-prandială."}],"correct":["A","B","C"],"pages":[339],"source":"set-2"}];
